import * as THREE from 'three'

const hairColors = [0x1b1512, 0x2c1f17, 0x4a3320, 0x111111, 0x6a4b2a, 0x3a2a1c]
const skins = [0x8d5524, 0xa8713c, 0xc68642, 0x6b4423, 0xe0ac69, 0x8a5a33]
const shirts = [0x1f6f8b, 0xb23b3b, 0x2f4f4f, 0xd9d4c7, 0x345c8a, 0x7a4f9e, 0x2c7a55, 0xc47a2a, 0x222429, 0xd8c36a]
const pants = [0x222b3a, 0x2d2d2d, 0x3f4a5a, 0x584a3a, 0x1c222b, 0x44525f]

function mat(color, rough = 0.85) {
  return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: 0.02 })
}

export function buildHuman(opts = {}) {
  const skin = opts.skin ?? skins[Math.floor(Math.random() * skins.length)]
  const shirt = opts.shirt ?? shirts[Math.floor(Math.random() * shirts.length)]
  const pant = opts.pants ?? pants[Math.floor(Math.random() * pants.length)]
  const hair = opts.hair ?? hairColors[Math.floor(Math.random() * hairColors.length)]
  const shoe = opts.shoe ?? 0x15171a
  const scale = opts.scale ?? (0.94 + Math.random() * 0.12)
  const sunglasses = opts.sunglasses ?? false
  const hat = opts.hat ?? false

  const group = new THREE.Group()
  const body = new THREE.Group()
  group.add(body)
  body.scale.setScalar(scale)

  const skinMat = mat(skin, 0.75)
  const shirtMat = mat(shirt, 0.9)
  const pantMat = mat(pant, 0.92)
  const shoeMat = mat(shoe, 0.55)
  const hairMat = mat(hair, 0.95)
  const darkMat = mat(0x101216, 0.5)

  // hips
  const hips = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.2, 0.24), pantMat)
  hips.position.y = 0.94
  hips.castShadow = true
  body.add(hips)

  // torso
  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.5, 0.26), shirtMat)
  torso.position.y = 1.25
  torso.castShadow = true
  body.add(torso)
  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.12, 0.27), shirtMat)
  chest.position.y = 1.44
  body.add(chest)

  // neck + head
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.07, 0.08, 8), skinMat)
  neck.position.y = 1.52
  body.add(neck)
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.135, 14, 12), skinMat)
  head.scale.set(0.92, 1.05, 0.95)
  head.position.y = 1.64
  head.castShadow = true
  body.add(head)

  // hair
  const hairMesh = new THREE.Mesh(new THREE.SphereGeometry(0.142, 12, 10, 0, Math.PI * 2, 0, Math.PI * 0.62), hairMat)
  hairMesh.position.y = 1.658
  hairMesh.scale.set(0.94, 1.05, 0.98)
  hairMesh.rotation.x = -0.12
  body.add(hairMesh)

  if (sunglasses) {
    const glasses = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.055, 0.03), darkMat)
    glasses.position.set(0, 1.665, 0.122)
    body.add(glasses)
  }
  if (hat) {
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.015, 14), mat(opts.hatColor ?? 0x20242a, 0.8))
    brim.position.y = 1.745
    const top = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.15, 0.1, 12), mat(opts.hatColor ?? 0x20242a, 0.8))
    top.position.y = 1.795
    group.add(brim, top)
  }

  // arms
  const armGeo = new THREE.CylinderGeometry(0.058, 0.05, 0.56, 7)
  const handGeo = new THREE.SphereGeometry(0.062, 8, 7)
  const makeArm = (side) => {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.29, 1.43, 0)
    const arm = new THREE.Mesh(armGeo, skinMat)
    arm.position.y = -0.28
    arm.castShadow = true
    const sleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.07, 0.16, 7), shirtMat)
    sleeve.position.y = -0.07
    const hand = new THREE.Mesh(handGeo, skinMat)
    hand.position.y = -0.57
    pivot.add(arm, sleeve, hand)
    body.add(pivot)
    return pivot
  }
  const armL = makeArm(-1)
  const armR = makeArm(1)

  // legs
  const legGeo = new THREE.CylinderGeometry(0.075, 0.065, 0.82, 7)
  const makeLeg = (side) => {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.105, 0.9, 0)
    const leg = new THREE.Mesh(legGeo, pantMat)
    leg.position.y = -0.41
    leg.castShadow = true
    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.09, 0.29), shoeMat)
    foot.position.set(0, -0.845, 0.05)
    foot.castShadow = true
    pivot.add(leg, foot)
    body.add(pivot)
    return pivot
  }
  const legL = makeLeg(-1)
  const legR = makeLeg(1)

  return { group, body, parts: { hips, torso, head, armL, armR, legL, legR, hairMesh } }
}

export function buildPistol() {
  const g = new THREE.Group()
  const metal = new THREE.MeshStandardMaterial({ color: 0x2a2d33, roughness: 0.35, metalness: 0.85 })
  const grip = new THREE.MeshStandardMaterial({ color: 0x1a1c20, roughness: 0.8 })
  const slide = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.075, 0.26), metal)
  slide.position.set(0, 0.03, 0.06)
  const frame = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.18), metal)
  frame.position.set(0, -0.02, 0.02)
  const handle = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.13, 0.07), grip)
  handle.position.set(0, -0.1, -0.035)
  handle.rotation.x = 0.16
  const muzzle = new THREE.Object3D()
  muzzle.position.set(0, 0.03, 0.2)
  g.add(slide, frame, handle, muzzle)
  g.userData.muzzle = muzzle
  return g
}

export function buildSMG() {
  const g = new THREE.Group()
  const metal = new THREE.MeshStandardMaterial({ color: 0x23262b, roughness: 0.4, metalness: 0.8 })
  const polymer = new THREE.MeshStandardMaterial({ color: 0x141619, roughness: 0.8 })
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.1, 0.34), metal)
  body.position.set(0, 0.02, 0.1)
  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.16, 8), metal)
  barrel.rotation.x = Math.PI / 2
  barrel.position.set(0, 0.035, 0.33)
  const mag = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.16, 0.07), polymer)
  mag.position.set(0, -0.1, 0.09)
  mag.rotation.x = -0.08
  const grip = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.12, 0.06), polymer)
  grip.position.set(0, -0.08, -0.04)
  const stock = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.05, 0.18), polymer)
  stock.position.set(0, 0.01, -0.14)
  const muzzle = new THREE.Object3D()
  muzzle.position.set(0, 0.035, 0.42)
  g.add(body, barrel, mag, grip, stock, muzzle)
  g.userData.muzzle = muzzle
  return g
}

import * as THREE from 'three'

function glowTexture(inner = 'rgba(255,240,200,1)', outer = 'rgba(255,120,30,0)', size = 128) {
  const c = document.createElement('canvas')
  c.width = c.height = size
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, inner)
  g.addColorStop(0.4, 'rgba(255,170,70,0.55)')
  g.addColorStop(1, outer)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, size, size)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

const _v = new THREE.Vector3()

export class Effects {
  constructor(scene, game) {
    this.scene = scene
    this.game = game
    this.group = new THREE.Group()
    scene.add(this.group)

    this.tracers = []
    for (let i = 0; i < 30; i++) {
      const geo = new THREE.BufferGeometry()
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3))
      const mat = new THREE.LineBasicMaterial({ color: 0xffd89a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false })
      const line = new THREE.Line(geo, mat)
      line.frustumCulled = false
      line.visible = false
      this.group.add(line)
      this.tracers.push({ line, life: 0, max: 0.08 })
    }

    this.maxParticles = 500
    const pGeo = new THREE.BufferGeometry()
    this.pPos = new Float32Array(this.maxParticles * 3)
    this.pCol = new Float32Array(this.maxParticles * 3)
    this.pVel = new Float32Array(this.maxParticles * 3)
    this.pLife = new Float32Array(this.maxParticles)
    this.pGrav = new Float32Array(this.maxParticles)
    pGeo.setAttribute('position', new THREE.BufferAttribute(this.pPos, 3))
    pGeo.setAttribute('color', new THREE.BufferAttribute(this.pCol, 3))
    const pMat = new THREE.PointsMaterial({
      size: 0.28, vertexColors: true, transparent: true, opacity: 0.95,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true
    })
    this.points = new THREE.Points(pGeo, pMat)
    this.points.frustumCulled = false
    this.group.add(this.points)

    this.smoke = []
    for (let i = 0; i < 24; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture('rgba(70,70,70,0.9)', 'rgba(20,20,20,0)', 64),
        transparent: true, opacity: 0, depthWrite: false, color: 0x333333
      }))
      s.visible = false
      this.group.add(s)
      this.smoke.push({ sprite: s, life: 0, max: 1.6, vel: new THREE.Vector3(), grow: 1 })
    }
    this.smokeIndex = 0

    this.flashes = []
    for (let i = 0; i < 10; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture('rgba(255,245,220,1)', 'rgba(255,160,60,0)', 128),
        transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending
      }))
      s.visible = false
      this.group.add(s)
      this.flashes.push({ sprite: s, life: 0, max: 0.12, scale: 1 })
    }
    this.flashIndex = 0
    this.light = new THREE.PointLight(0xffa050, 0, 45, 2)
    this.group.add(this.light)
    this.lightLife = 0
    this.pIndex = 0
    this.shake = 0
  }

  tracer(a, b) {
    const t = this.tracers.find(t => t.life <= 0) || this.tracers[0]
    const pos = t.line.geometry.attributes.position
    pos.setXYZ(0, a.x, a.y, a.z)
    pos.setXYZ(1, b.x, b.y, b.z)
    pos.needsUpdate = true
    t.line.visible = true
    t.life = t.max
    t.line.material.opacity = 1
  }

  burst(pos, count = 12, color = 0xffc070, speed = 5, life = 0.45, gravity = -9) {
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const idx = this.pIndex++ % this.maxParticles
      this.pPos[idx * 3] = pos.x
      this.pPos[idx * 3 + 1] = pos.y
      this.pPos[idx * 3 + 2] = pos.z
      const dir = _v.set(Math.random() - 0.5, Math.random() - 0.3, Math.random() - 0.5).normalize().multiplyScalar(speed * (0.4 + Math.random()))
      this.pVel[idx * 3] = dir.x
      this.pVel[idx * 3 + 1] = dir.y
      this.pVel[idx * 3 + 2] = dir.z
      this.pLife[idx] = life * (0.6 + Math.random() * 0.8)
      this.pGrav[idx] = gravity
      this.pCol[idx * 3] = c.r
      this.pCol[idx * 3 + 1] = c.g
      this.pCol[idx * 3 + 2] = c.b
    }
    this.points.geometry.attributes.position.needsUpdate = true
    this.points.geometry.attributes.color.needsUpdate = true
  }

  flash(pos, scale = 0.6, time = 0.09) {
    const f = this.flashes[this.flashIndex++ % this.flashes.length]
    f.sprite.position.copy(pos)
    f.sprite.visible = true
    f.sprite.material.opacity = 1
    f.scale = scale
    f.sprite.scale.setScalar(scale)
    f.life = time
    f.max = time
    this.light.position.copy(pos)
    this.light.intensity = 8
    this.lightLife = time
  }

  puff(pos, color = 0x3a3a3a, scale = 1) {
    const s = this.smoke[this.smokeIndex++ % this.smoke.length]
    s.sprite.position.copy(pos)
    s.sprite.visible = true
    s.sprite.material.color.setHex(color)
    s.sprite.material.opacity = 0.75
    s.sprite.scale.setScalar(scale)
    s.life = s.max
    s.grow = scale
    s.vel.set(Math.random() - 0.5, 1 + Math.random(), Math.random() - 0.5).multiplyScalar(0.5)
  }

  explosion(pos) {
    this.burst(pos, 60, 0xffa03a, 13, 0.9, -6)
    this.burst(pos, 30, 0xffe6a0, 7, 0.5, -3)
    this.flash(pos, 4.5, 0.35)
    for (let i = 0; i < 8; i++) this.puff(pos.clone().add(new THREE.Vector3((Math.random() - .5) * 3, Math.random() * 2, (Math.random() - .5) * 3)), 0x222222, 2 + Math.random() * 2)
    this.shake = Math.max(this.shake, 0.6)
    if (this.game.audio) this.game.audio.explosion()
  }

  update(dt) {
    for (const t of this.tracers) {
      if (t.life > 0) {
        t.life -= dt
        t.line.material.opacity = Math.max(0, t.life / t.max)
        if (t.life <= 0) t.line.visible = false
      }
    }
    let any = false
    for (let i = 0; i < this.maxParticles; i++) {
      if (this.pLife[i] > 0) {
        any = true
        this.pLife[i] -= dt
        this.pPos[i * 3] += this.pVel[i * 3] * dt
        this.pPos[i * 3 + 1] += this.pVel[i * 3 + 1] * dt
        this.pPos[i * 3 + 2] += this.pVel[i * 3 + 2] * dt
        this.pVel[i * 3 + 1] += this.pGrav[i] * dt
        const k = Math.max(0, this.pLife[i])
        const f = Math.min(1, k * 2.2)
        this.pCol[i * 3] *= 0.995
        this.pCol[i * 3 + 1] *= 0.992
        this.pCol[i * 3 + 2] *= 0.99
        if (this.pLife[i] <= 0) {
          this.pPos[i * 3 + 1] = -1000
        }
        if (f < 1) {
          this.pCol[i * 3] *= 0.97
          this.pCol[i * 3 + 1] *= 0.97
          this.pCol[i * 3 + 2] *= 0.97
        }
      }
    }
    if (any) {
      this.points.geometry.attributes.position.needsUpdate = true
      this.points.geometry.attributes.color.needsUpdate = true
    }
    for (const s of this.smoke) {
      if (s.life > 0) {
        s.life -= dt
        const f = s.life / s.max
        s.sprite.position.addScaledVector(s.vel, dt)
        s.sprite.position.y += dt * 0.6
        s.sprite.material.opacity = Math.max(0, f) * 0.7
        s.sprite.scale.setScalar(s.grow * (1 + (1 - f) * 1.8))
        if (s.life <= 0) s.sprite.visible = false
      }
    }
    for (const f of this.flashes) {
      if (f.life > 0) {
        f.life -= dt
        const k = Math.max(0, f.life / f.max)
        f.sprite.material.opacity = k
        f.sprite.scale.setScalar(f.scale * (1 + (1 - k) * 0.8))
        if (f.life <= 0) f.sprite.visible = false
      }
    }
    if (this.lightLife > 0) {
      this.lightLife -= dt
      this.light.intensity = Math.max(0, this.lightLife * 30)
    }
    this.shake = Math.max(0, this.shake - dt * 1.5)
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.muted = false
    this.started = false
    this.engineGain = null
    this.sirenGain = null
  }

  init() {
    if (this.started) { if (this.ctx?.state === 'suspended') this.ctx.resume(); return }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    const ctx = new AC()
    this.ctx = ctx
    this.started = true
    this.master = ctx.createGain()
    this.master.gain.value = 0.75
    this.master.connect(ctx.destination)

    // Shared noise buffer
    const len = ctx.sampleRate * 2
    const buf = ctx.createBuffer(1, len, ctx.sampleRate)
    const d = buf.getChannelData(0)
    let last = 0
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1
      last = (last + 0.02 * white) / 1.02
      d[i] = last * 3.2
    }
    this.noise = buf

    // Engine hum
    this.engineGain = ctx.createGain()
    this.engineGain.gain.value = 0
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.value = 380
    lp.Q.value = 3
    const o1 = ctx.createOscillator()
    o1.type = 'sawtooth'
    o1.frequency.value = 55
    const o2 = ctx.createOscillator()
    o2.type = 'square'
    o2.frequency.value = 27.5
    const g2 = ctx.createGain(); g2.gain.value = 0.4
    o1.connect(lp); o2.connect(g2); g2.connect(lp)
    lp.connect(this.engineGain); this.engineGain.connect(this.master)
    o1.start(); o2.start()
    this.engineOsc = [o1, o2]
    this.engineFilter = lp

    // Siren
    this.sirenGain = ctx.createGain()
    this.sirenGain.gain.value = 0
    const sg = ctx.createGain(); sg.gain.value = 0.18
    const s1 = ctx.createOscillator(); s1.type = 'square'; s1.frequency.value = 680
    const lfo = ctx.createOscillator(); lfo.type = 'sine'; lfo.frequency.value = 0.45
    const lfoGain = ctx.createGain(); lfoGain.gain.value = 240
    lfo.connect(lfoGain); lfoGain.connect(s1.frequency)
    s1.connect(sg); sg.connect(this.sirenGain); this.sirenGain.connect(this.master)
    s1.start(); lfo.start()
    this.sirenOsc = s1

    // City ambience
    const amb = ctx.createBufferSource()
    amb.buffer = buf
    amb.loop = true
    const ambF = ctx.createBiquadFilter()
    ambF.type = 'lowpass'
    ambF.frequency.value = 400
    const ambG = ctx.createGain()
    ambG.gain.value = 0.05
    amb.connect(ambF); ambF.connect(ambG); ambG.connect(this.master)
    amb.start()
    this.ambience = ambG
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.value = m ? 0 : 0.75
  }

  noiseBurst(dur, freq, gain, type = 'lowpass', q = 1) {
    if (!this.ctx || this.muted) return
    const ctx = this.ctx
    const src = ctx.createBufferSource()
    src.buffer = this.noise
    src.playbackRate.value = 0.8 + Math.random() * 0.5
    const f = ctx.createBiquadFilter()
    f.type = type
    f.frequency.value = freq
    f.Q.value = q
    const g = ctx.createGain()
    const t = ctx.currentTime
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(f); f.connect(g); g.connect(this.master)
    src.start(t, Math.random())
    src.stop(t + dur + 0.02)
  }

  tone(freq, dur, gain = 0.15, type = 'sine', slide = 0) {
    if (!this.ctx || this.muted) return
    const ctx = this.ctx
    const o = ctx.createOscillator()
    o.type = type
    const g = ctx.createGain()
    const t = ctx.currentTime
    o.frequency.setValueAtTime(freq, t)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur)
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g); g.connect(this.master)
    o.start(t); o.stop(t + dur + 0.02)
  }

  gunshot(kind = 'pistol') {
    this.noiseBurst(kind === 'smg' ? 0.1 : 0.18, kind === 'smg' ? 1800 : 1300, 0.5, 'bandpass', 0.7)
    this.tone(kind === 'smg' ? 120 : 82, 0.09, 0.28, 'square', -40)
    this.tone(1600, 0.03, 0.08, 'triangle', -900)
  }

  reload() {
    this.tone(520, 0.05, 0.06, 'square')
    setTimeout(() => this.tone(360, 0.05, 0.05, 'square'), 160)
  }

  footstep() {
    this.noiseBurst(0.06, 900, 0.05, 'lowpass', 0.5)
  }

  crash(intensity = 1) {
    this.noiseBurst(0.25, 500, Math.min(0.55, 0.18 + intensity * 0.25), 'lowpass', 0.8)
    this.tone(65, 0.2, 0.2, 'sine', -20)
  }

  explosion() {
    this.noiseBurst(0.9, 700, 0.75, 'lowpass', 0.5)
    this.tone(55, 0.7, 0.45, 'sine', -35)
    this.tone(120, 0.4, 0.2, 'sawtooth', -80)
  }

  bulletImpact() {
    this.noiseBurst(0.05, 2600, 0.08, 'highpass', 1)
  }

  hitFlesh() {
    this.tone(140, 0.08, 0.12, 'square', -60)
    this.noiseBurst(0.08, 500, 0.1)
  }

  missionComplete() {
    const notes = [523, 659, 784, 1046]
    notes.forEach((n, i) => setTimeout(() => this.tone(n, 0.3, 0.14, 'triangle'), i * 110))
  }

  missionStart() {
    const notes = [392, 523, 659]
    notes.forEach((n, i) => setTimeout(() => this.tone(n, 0.25, 0.11, 'triangle'), i * 90))
  }

  fail() {
    this.tone(220, 0.4, 0.16, 'sawtooth', -120)
    setTimeout(() => this.tone(150, 0.5, 0.14, 'sawtooth', -80), 260)
  }

  click() {
    this.tone(880, 0.04, 0.05, 'square')
  }

  update(dt, { driving, speed, throttle, wanted, sirenDist, paused }) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    if (this.engineGain) {
      const target = driving && !paused ? 0.10 + Math.min(0.12, Math.abs(speed) * 0.003) + (throttle ? 0.04 : 0) : 0
      this.engineGain.gain.setTargetAtTime(target, t, 0.08)
      if (driving) {
        const f = 42 + Math.abs(speed) * 5.5 + (throttle ? 12 : 0)
        this.engineOsc[0].frequency.setTargetAtTime(f, t, 0.06)
        this.engineOsc[1].frequency.setTargetAtTime(f / 2, t, 0.06)
        this.engineFilter.frequency.setTargetAtTime(260 + Math.abs(speed) * 26, t, 0.08)
      }
    }
    if (this.sirenGain) {
      let g = 0
      if (wanted > 0 && sirenDist != null) g = Math.max(0, 1 - sirenDist / 90) * 0.35
      this.sirenGain.gain.setTargetAtTime(g, t, 0.15)
    }
  }
}

import * as THREE from 'three'

export const CAR_TYPES = {
  sedan: { l: 4.5, w: 1.86, roof: 1.32, accel: 12, brake: 24, maxSpeed: 27, grip: 7.0, steerRate: 1.9 },
  sports: { l: 4.4, w: 1.98, roof: 1.12, accel: 19, brake: 28, maxSpeed: 37, grip: 8.0, steerRate: 2.15 },
  police: { l: 4.6, w: 1.9, roof: 1.34, accel: 15, brake: 26, maxSpeed: 33, grip: 7.4, steerRate: 2.0 },
  taxi: { l: 4.5, w: 1.86, roof: 1.34, accel: 12, brake: 24, maxSpeed: 26, grip: 7.0, steerRate: 1.9 },
  van: { l: 5.2, w: 2.02, roof: 1.96, accel: 9.5, brake: 22, maxSpeed: 21, grip: 6.2, steerRate: 1.6 }
}

const PAINT = [0xd8d8d8, 0x1a1c20, 0x8c9298, 0x8c1f1f, 0x1f3f75, 0x2a5b3a, 0xc06a1c, 0x3a3d44, 0xd6c8a2, 0x6a1f2a]

function glowTex(text, fg = '#f6f6f6', bg = 'rgba(0,0,0,0)') {
  const c = document.createElement('canvas')
  c.width = 512; c.height = 128
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 512, 128)
  ctx.fillStyle = bg; ctx.fillRect(0, 0, 512, 128)
  ctx.fillStyle = fg
  ctx.font = 'bold 82px Arial Black, Arial, sans-serif'
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
  ctx.fillText(text, 256, 68)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

function extrudeProfile(points, width) {
  const shape = new THREE.Shape()
  shape.moveTo(points[0][0], points[0][1])
  for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1])
  shape.closePath()
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: width, bevelEnabled: true, bevelSize: 0.05, bevelThickness: 0.05, bevelSegments: 2, steps: 1, curveSegments: 1
  })
  geo.translate(0, 0, -width / 2)
  geo.rotateY(-Math.PI / 2)
  return geo
}

export function buildCar(type = 'sedan', color) {
  const cfg = CAR_TYPES[type] || CAR_TYPES.sedan
  const l = cfg.l, w = cfg.w
  const group = new THREE.Group()
  const paintColor = color ?? (type === 'police' ? 0x1b1e24 : type === 'taxi' ? 0xe8b52a : PAINT[Math.floor(Math.random() * PAINT.length)])
  const paint = new THREE.MeshPhysicalMaterial({
    color: paintColor, metalness: 0.62, roughness: 0.28, clearcoat: 0.9, clearcoatRoughness: 0.12, envMapIntensity: 1.1
  })
  const trimMat = new THREE.MeshStandardMaterial({ color: 0x15171a, roughness: 0.6, metalness: 0.4 })
  const glass = new THREE.MeshPhysicalMaterial({
    color: 0x0b141c, metalness: 0.2, roughness: 0.06, clearcoat: 1, envMapIntensity: 1.5
  })
  const chrome = new THREE.MeshStandardMaterial({ color: 0xc9ccd1, metalness: 0.95, roughness: 0.18 })

  // lower body
  const bodyPts = [
    [-l * 0.47, 0.26], [-l * 0.49, 0.6], [-l * 0.36, 0.78],
    [l * 0.36, 0.78], [l * 0.49, 0.6], [l * 0.47, 0.3], [l * 0.3, 0.2], [-l * 0.3, 0.2]
  ]
  const lower = new THREE.Mesh(extrudeProfile(bodyPts, w - 0.08), paint)
  lower.castShadow = true
  lower.receiveShadow = true
  group.add(lower)

  // cabin
  const r = cfg.roof
  let cabinPts
  if (type === 'van') {
    cabinPts = [[-l * 0.4, 0.76], [-l * 0.4, r], [l * 0.18, r], [l * 0.34, 0.76]]
  } else if (type === 'sports') {
    cabinPts = [[-l * 0.24, 0.76], [-l * 0.1, r], [l * 0.14, r], [l * 0.3, 0.76]]
  } else {
    cabinPts = [[-l * 0.3, 0.76], [-l * 0.12, r], [l * 0.14, r], [l * 0.3, 0.76]]
  }
  const cabin = new THREE.Mesh(extrudeProfile(cabinPts, w - 0.16), glass)
  cabin.castShadow = true
  group.add(cabin)

  // roof panel
  const roofLen = type === 'van' ? l * 0.56 : l * 0.25
  const roofZ = type === 'van' ? -l * 0.11 : l * 0.005
  const roof = new THREE.Mesh(new THREE.BoxGeometry(w - 0.24, 0.07, roofLen), paint)
  roof.position.set(0, r + 0.015, roofZ)
  roof.castShadow = true
  group.add(roof)

  // pillars + interior block
  const interior = new THREE.Mesh(new THREE.BoxGeometry(w - 0.3, 0.42, l * 0.46), new THREE.MeshStandardMaterial({ color: 0x14161a, roughness: .9 }))
  interior.position.set(0, 0.95, 0)
  group.add(interior)

  // wheels
  const wheelR = type === 'sports' ? 0.35 : type === 'van' ? 0.38 : 0.34
  const wheelW = 0.26
  const wheelGeo = new THREE.CylinderGeometry(wheelR, wheelR, wheelW, 18)
  wheelGeo.rotateZ(Math.PI / 2)
  const tyreMat = new THREE.MeshStandardMaterial({ color: 0x111214, roughness: 0.85, metalness: 0.05 })
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xbfc3c7, roughness: 0.25, metalness: 0.95 })
  const hubGeo = new THREE.CylinderGeometry(wheelR * 0.55, wheelR * 0.55, wheelW + 0.02, 10)
  hubGeo.rotateZ(Math.PI / 2)
  const wheels = []
  const zOff = l * 0.3
  const xOff = w / 2 - 0.05
  for (const [sx, sz, front] of [[-1, 1, true], [1, 1, true], [-1, -1, false], [1, -1, false]]) {
    const pivot = new THREE.Group()
    pivot.position.set(sx * xOff, wheelR, sz * zOff)
    const tyre = new THREE.Mesh(wheelGeo, tyreMat)
    tyre.castShadow = true
    const hub = new THREE.Mesh(hubGeo, rimMat)
    hub.position.x = sx * 0.005
    pivot.add(tyre, hub)
    group.add(pivot)
    wheels.push({ pivot, tyre, front })
  }

  // lights
  const headMat = new THREE.MeshStandardMaterial({ color: 0xfff4d2, emissive: 0xfff0c0, emissiveIntensity: 2.2, roughness: .2 })
  const tailMat = new THREE.MeshStandardMaterial({ color: 0x8a0f12, emissive: 0xff1d20, emissiveIntensity: 1.4, roughness: .3 })
  const headGeo = new THREE.BoxGeometry(0.36, 0.14, 0.06)
  for (const sx of [-1, 1]) {
    const h = new THREE.Mesh(headGeo, headMat)
    h.position.set(sx * (w / 2 - 0.38), 0.6, l * 0.475)
    group.add(h)
    const t = new THREE.Mesh(headGeo, tailMat)
    t.position.set(sx * (w / 2 - 0.38), 0.62, -l * 0.475)
    group.add(t)
  }

  // bumpers + plate
  const bumperGeo = new THREE.BoxGeometry(w * 0.92, 0.18, 0.16)
  const fb = new THREE.Mesh(bumperGeo, trimMat)
  fb.position.set(0, 0.35, l * 0.48)
  const rb = new THREE.Mesh(bumperGeo, trimMat)
  rb.position.set(0, 0.35, -l * 0.48)
  group.add(fb, rb)
  const plate = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.14, 0.03), new THREE.MeshStandardMaterial({ color: 0xe9e6da, roughness: .5 }))
  plate.position.set(0, 0.47, -l * 0.49)
  group.add(plate)

  // mirrors
  for (const sx of [-1, 1]) {
    const mirror = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.08, 0.2), paint)
    mirror.position.set(sx * (w / 2 + 0.03), 0.86, l * 0.16)
    group.add(mirror)
  }

  // grille
  const grille = new THREE.Mesh(new THREE.BoxGeometry(w * 0.42, 0.14, 0.05), chrome)
  grille.position.set(0, 0.52, l * 0.49)
  group.add(grille)

  let lightbar = null
  let sirenMats = null
  if (type === 'police') {
    // livery panels
    const blackPanel = new THREE.MeshStandardMaterial({ color: 0x101216, roughness: .45, metalness: .3 })
    for (const sx of [-1, 1]) {
      const panel = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.34, 1.8), blackPanel)
      panel.position.set(sx * (w / 2 + 0.005), 0.56, 0.05)
      group.add(panel)
      const decal = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 0.32), new THREE.MeshBasicMaterial({ map: glowTex('POLICE', '#f3f3ef'), transparent: true }))
      decal.position.set(sx * (w / 2 + 0.03), 0.66, 0.05)
      decal.rotation.y = sx * Math.PI / 2
      group.add(decal)
    }
    const hood = new THREE.Mesh(new THREE.BoxGeometry(w * 0.86, 0.02, l * 0.26), blackPanel)
    hood.position.set(0, 0.79, l * 0.3)
    group.add(hood)
    // light bar
    lightbar = new THREE.Group()
    const barBase = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.07, 0.24), trimMat)
    const redMat = new THREE.MeshStandardMaterial({ color: 0xff1a1a, emissive: 0xff0000, emissiveIntensity: 2.5 })
    const blueMat = new THREE.MeshStandardMaterial({ color: 0x1a5bff, emissive: 0x0033ff, emissiveIntensity: 2.5 })
    const red = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.12, 0.2), redMat)
    const blue = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.12, 0.2), blueMat)
    red.position.x = -0.24
    blue.position.x = 0.24
    lightbar.add(barBase, red, blue)
    lightbar.position.set(0, r + 0.1, -0.05)
    group.add(lightbar)
    sirenMats = { red: redMat, blue: blueMat }
    // push bar
    const bar = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.4, 0.08), trimMat)
    bar.position.set(0, 0.5, l * 0.51)
    group.add(bar)
  }
  if (type === 'taxi') {
    const sign = new THREE.Mesh(new THREE.BoxGeometry(0.66, 0.22, 0.28), new THREE.MeshStandardMaterial({ color: 0xe8c14a, emissive: 0x966d10, emissiveIntensity: 0.7 }))
    sign.position.set(0, r + 0.14, 0.1)
    group.add(sign)
    const decalMat = new THREE.MeshBasicMaterial({ map: glowTex('TAXI', '#1b1b1b'), transparent: true })
    const d = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 0.16), decalMat)
    d.position.set(0, r + 0.14, 0.245)
    group.add(d)
  }
  if (type === 'sports') {
    const spoiler = new THREE.Mesh(new THREE.BoxGeometry(w * 0.8, 0.06, 0.34), paint)
    spoiler.position.set(0, 0.92, -l * 0.4)
    const strutGeo = new THREE.BoxGeometry(0.06, 0.18, 0.1)
    for (const sx of [-1, 1]) {
      const s = new THREE.Mesh(strutGeo, trimMat)
      s.position.set(sx * w * 0.3, 0.82, -l * 0.4)
      group.add(s)
    }
    group.add(spoiler)
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.008, l * 0.8), new THREE.MeshStandardMaterial({ color: 0xf2f0e8, roughness: .4 }))
    stripe.position.set(0, 0.795, 0)
    group.add(stripe)
  }
  if (type === 'van') {
    const rack = new THREE.Mesh(new THREE.BoxGeometry(w * 0.7, 0.05, l * 0.4), trimMat)
    rack.position.set(0, r + 0.08, -l * 0.1)
    group.add(rack)
  }

  // shooting proxy
  const proxy = new THREE.Mesh(new THREE.BoxGeometry(w, r, l), new THREE.MeshBasicMaterial())
  proxy.visible = false
  proxy.position.y = r / 2 + 0.2
  group.add(proxy)

  return { group, wheels, lightbar, sirenMats, headMat, tailMat, dims: { l, w, h: r }, proxy }
}

function damp(a, b, lambda, dt) { return a + (b - a) * (1 - Math.exp(-lambda * dt)) }

export function angleLerp(a, b, t) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI
  if (d < -Math.PI) d += Math.PI * 2
  return a + d * t
}

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)) }

export class VehicleSystem {
  constructor(scene, game, world) {
    this.scene = scene
    this.game = game
    this.world = world
    this.vehicles = []
    this.playerVehicle = null
    this.root = new THREE.Group()
    scene.add(this.root)
    this.spawnTimer = 0
  }

  addVehicle(type, color, x, z, yaw, options = {}) {
    const built = buildCar(type, color)
    const v = {
      type,
      ...built,
      pos: new THREE.Vector3(x, 0, z),
      yaw,
      speed: 0,
      vel: new THREE.Vector3(),
      steer: 0,
      hp: options.hp ?? (type === 'police' ? 160 : 120),
      maxHp: options.hp ?? (type === 'police' ? 160 : 120),
      driver: options.driver ?? null,
      traffic: options.traffic ?? false,
      destroyed: false,
      ai: options.ai ?? null,
      isPolice: type === 'police',
      brakeLight: false,
      color: color ?? null,
      cruise: options.cruise ?? 9 + Math.random() * 4,
      sirenPhase: Math.random() * Math.PI * 2,
      damageSmoke: 0,
      stuck: 0
    }
    v.group.position.copy(v.pos)
    v.group.rotation.y = yaw
    v.proxy.userData = { type: 'vehicle', ref: v }
    this.root.add(v.group)
    this.vehicles.push(v)
    return v
  }

  /* ------------------------------------------------------------- spawning */
  start() {
    this.spawnParked()
    for (let i = 0; i < 12; i++) this.spawnTraffic()
  }

  spawnParked() {
    const spots = []
    for (const line of [GRID_PLACEHOLDER]) { /* noop */ }
    const grid = [-160, -96, -32, 32, 96, 160]
    for (let k = 0; k < 18; k++) {
      const line = grid[1 + Math.floor(Math.random() * 4)]
      const along = -150 + Math.random() * 300
      const side = Math.random() < 0.5 ? -1 : 1
      const axis = Math.random() < 0.5 ? 0 : 1
      let x, z, yaw
      if (axis === 0) {
        x = line + side * (8 - 1.3)
        z = along
        yaw = side > 0 ? Math.PI : 0
      } else {
        x = along
        z = line + side * (8 - 1.3)
        yaw = side > 0 ? Math.PI / 2 : -Math.PI / 2
      }
      if (spots.some(s => Math.hypot(s.x - x, s.z - z) < 9)) continue
      spots.push({ x, z })
      const types = ['sedan', 'sedan', 'sports', 'van', 'taxi']
      const t = types[Math.floor(Math.random() * types.length)]
      this.addVehicle(t, undefined, x, z, yaw)
    }
    // Hero sports car near spawn for the first mission
    this.heroCar = this.addVehicle('sports', 0xd8321f, 38.5, 56, Math.PI, {})
    this.heroCar.hero = true
    // Simeon's garage marker car / delivery van landmarks
    this.addVehicle('van', 0x2d3a4a, 34.2, 104, 0, {})
  }

  randomTrafficStart() {
    const grid = [-160, -96, -32, 32, 96, 160]
    const i = 1 + Math.floor(Math.random() * 4)
    const j = 1 + Math.floor(Math.random() * 4)
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]]
    const d = dirs[Math.floor(Math.random() * 4)]
    const x = grid[i] + d[0] * (10 + Math.random() * 30)
    const z = grid[j] + d[1] * (10 + Math.random() * 30)
    const yaw = Math.atan2(d[0], d[1])
    return { x, z, yaw, i, j, d }
  }

  spawnTraffic() {
    const s = this.randomTrafficStart()
    const types = ['sedan', 'sedan', 'taxi', 'sports', 'van', 'sedan']
    const v = this.addVehicle(types[Math.floor(Math.random() * types.length)], undefined, s.x, s.z, s.yaw, { driver: 'ai', traffic: true })
    v.ai = {
      mode: 'traffic',
      i: s.i, j: s.j,
      dir: { x: s.d[0], z: s.d[1] },
      target: new THREE.Vector3(),
      speed: 8,
      next: null
    }
    this.chooseTrafficTarget(v, true)
    // avoid spawning on top of the player
    const p = this.game.player
    if (p && p.pos.distanceTo(v.pos) < 25) {
      v.pos.x *= 1.35; v.pos.z *= 1.35
      v.group.position.copy(v.pos)
    }
    return v
  }

  chooseTrafficTarget(v, first = false) {
    const grid = [-160, -96, -32, 32, 96, 160]
    const ai = v.ai
    let ni = ai.i + ai.dir.x
    let nj = ai.j + ai.dir.z
    if (first || ni < 0 || ni > 5 || nj < 0 || nj > 5 || Math.random() < 0.18) {
      const candidates = [[1, 0], [-1, 0], [0, 1], [0, -1]].filter(([dx, dz]) => {
        if (dx === -ai.dir.x && dz === -ai.dir.z) return false
        const x = ai.i + dx, z = ai.j + dz
        return x >= 0 && x <= 5 && z >= 0 && z <= 5
      })
      if (!candidates.length) {
        ai.dir = { x: -ai.dir.x, z: -ai.dir.z }
      } else {
        const straight = candidates.find(([dx, dz]) => dx === ai.dir.x && dz === ai.dir.z)
        let pick
        if (straight && Math.random() < 0.55) pick = straight
        else pick = candidates[Math.floor(Math.random() * candidates.length)]
        ai.dir = { x: pick[0], z: pick[1] }
      }
      ni = ai.i + ai.dir.x
      nj = ai.j + ai.dir.z
      ai.i = clamp(ai.i, 0, 5)
      ai.j = clamp(ai.j, 0, 5)
      if (ni < 0 || ni > 5 || nj < 0 || nj > 5) {
        ai.dir = { x: ai.dir.x * -1, z: ai.dir.z * -1 }
        ni = ai.i + ai.dir.x
        nj = ai.j + ai.dir.z
      }
    }
    ai.next = { i: ni, j: nj }
    const right = { x: ai.dir.z, z: -ai.dir.x }
    ai.target.set(grid[ni] + right.x * 4, 0, grid[nj] + right.z * 4)
    ai.node = { i: ai.i, j: ai.j }
  }

  /* -------------------------------------------------------------- driver */
  findNearest(pos, maxDist = 4.2) {
    let best = null
    for (const v of this.vehicles) {
      if (v.destroyed) continue
      const d = Math.hypot(v.pos.x - pos.x, v.pos.z - pos.z)
      if (d < maxDist && (!best || d < best.dist)) best = { vehicle: v, dist: d }
    }
    return best
  }

  enter(v) {
    if (!v || v.destroyed) return false
    this.playerVehicle = v
    v.driver = 'player'
    v.traffic = false
    v.ai = null
    this.game.player.inCar = true
    this.game.player.group.visible = false
    this.game.hud.setDriving(true)
    this.game.audio.init()
    if (v.hero) this.game.missions.notifyVehicleStolen(v)
    return true
  }

  exit() {
    const v = this.playerVehicle
    if (!v) return false
    if (Math.abs(v.speed) > 8) return false
    const fwd = new THREE.Vector3(Math.sin(v.yaw), 0, Math.cos(v.yaw))
    const right = new THREE.Vector3(fwd.z, 0, -fwd.x)
    const p = this.game.player
    p.pos.copy(v.pos).addScaledVector(right, -2.2)
    p.pos.y = 0
    this.world.resolveCircle(p.pos, 0.5)
    p.vel.set(0, 0, 0)
    p.group.position.copy(p.pos)
    p.group.visible = true
    p.inCar = false
    p.yaw = v.yaw
    v.driver = null
    v.traffic = false
    v.ai = null
    v.vel.set(0, 0, 0)
    v.speed = 0
    this.playerVehicle = null
    this.game.hud.setDriving(false)
    return true
  }

  /* -------------------------------------------------------------- update */
  update(dt) {
    const input = this.game.input
    if (this.playerVehicle) this.updatePlayerVehicle(dt, input)
    for (const v of this.vehicles) {
      if (v === this.playerVehicle) continue
      if (v.driver === 'ai' && v.ai) {
        if (v.ai.mode === 'traffic') this.updateTraffic(dt, v)
        else if (v.ai.mode === 'police') this.updatePoliceCar(dt, v)
      }
      if (v.destroyed) continue
      this.updateVisual(dt, v)
    }
    if (this.playerVehicle) this.updateVisual(dt, this.playerVehicle, true)
    this.collideVehicles(dt)
    this.maintainTraffic(dt)
  }

  updatePlayerVehicle(dt, input) {
    const v = this.playerVehicle
    if (!v) return
    const throttle = input.throttle
    const brake = input.brake
    const steerIn = input.steer
    const handbrake = input.handbrake
    v.steer = damp(v.steer, steerIn, 7, dt)

    const fwd = new THREE.Vector3(Math.sin(v.yaw), 0, Math.cos(v.yaw))
    const right = new THREE.Vector3(fwd.z, 0, -fwd.x)
    let fSpeed = v.vel.dot(fwd)
    let rSpeed = v.vel.dot(right)

    if (throttle > 0) {
      const max = v.maxSpeed
      fSpeed += v.accel * throttle * dt * Math.max(0.08, 1 - Math.abs(fSpeed) / max * 0.75)
    }
    if (brake > 0) {
      if (fSpeed > 0.4) fSpeed -= v.brake * brake * dt
      else fSpeed -= v.accel * 0.55 * brake * dt
    }
    // rolling resistance
    const roll = 1.4 + Math.abs(fSpeed) * 0.04
    if (Math.abs(fSpeed) < 0.15 && !throttle) fSpeed = 0
    else fSpeed -= Math.sign(fSpeed) * Math.min(Math.abs(fSpeed), roll * dt)
    // air drag
    fSpeed -= fSpeed * Math.abs(fSpeed) * 0.0018 * dt * 60
    fSpeed = clamp(fSpeed, -v.maxSpeed * 0.34, v.maxSpeed)

    // lateral grip
    const grip = handbrake ? 1.1 : v.grip
    rSpeed *= Math.exp(-grip * dt)

    // steering
    const sf = Math.min(1, Math.abs(fSpeed) / 5.5)
    const dirSign = fSpeed >= 0 ? 1 : -1
    v.yaw += v.steer * v.steerRate * sf * dirSign * dt * (handbrake ? 1.3 : 1)

    const fwd2 = new THREE.Vector3(Math.sin(v.yaw), 0, Math.cos(v.yaw))
    const right2 = new THREE.Vector3(fwd2.z, 0, -fwd2.x)
    v.vel.copy(fwd2).multiplyScalar(fSpeed).addScaledVector(right2, rSpeed)
    v.speed = fSpeed

    const prev = v.pos.clone()
    v.pos.addScaledVector(v.vel, dt)
    this.world.resolveCircle(v.pos, 1.15)
    const moved = v.pos.distanceTo(prev)
    if (moved < v.vel.length() * dt * 0.55 && v.vel.length() > 4) {
      // crashed into a wall
      const impact = v.vel.length()
      v.vel.multiplyScalar(0.15)
      v.speed *= 0.15
      if (impact > 6) {
        this.game.effects.burst(new THREE.Vector3(v.pos.x, 0.7, v.pos.z), 10, 0xffb060, 5, 0.5, -12)
        this.game.audio.crash(impact / 20)
        this.game.effects.shake = Math.max(this.game.effects.shake, Math.min(0.5, impact / 50))
        this.damageVehicle(v, impact * 0.7)
        if (this.game.player.inCar) this.game.player.takeDamage(impact * 0.4, 'crash', true)
      }
    }

    // traffic avoidance: stop if a car is directly ahead
    // (handled by collideVehicles)

    if (v.hp <= 0 && !v.destroyed) this.explodeVehicle(v)
  }

  updateTraffic(dt, v) {
    const ai = v.ai
    const dx = ai.target.x - v.pos.x
    const dz = ai.target.z - v.pos.z
    const dist = Math.hypot(dx, dz)
    if (dist < 7) {
      ai.i = ai.next.i
      ai.j = ai.next.j
      this.chooseTrafficTarget(v)
    }
    const desiredYaw = Math.atan2(ai.target.x - v.pos.x, ai.target.z - v.pos.z)
    const diff = Math.abs(((desiredYaw - v.yaw + Math.PI) % (Math.PI * 2)) - Math.PI)
    let targetSpeed = v.cruise * (diff > 0.5 ? 0.45 : 1)
    // yield to player
    const p = this.game.player
    if (p) {
      const pd = p.pos.distanceTo(v.pos)
      if (!p.inCar && pd < 6) targetSpeed = 0
    }
    // stop for player's car ahead
    if (this.playerVehicle) {
      const toP = this.playerVehicle.pos.clone().sub(v.pos)
      const fwd = new THREE.Vector3(Math.sin(v.yaw), 0, Math.cos(v.yaw))
      if (toP.length() < 13 && toP.dot(fwd) > 0) targetSpeed = Math.min(targetSpeed, Math.max(0, (toP.length() - 4) * 0.8))
    }
    ai.speed = damp(ai.speed, targetSpeed, 1.5, dt)
    v.yaw = angleLerp(v.yaw, desiredYaw, Math.min(1, dt * 3.2))
    v.pos.x += Math.sin(v.yaw) * ai.speed * dt
    v.pos.z += Math.cos(v.yaw) * ai.speed * dt
    v.speed = ai.speed
    v.vel.set(Math.sin(v.yaw) * ai.speed, 0, Math.cos(v.yaw) * ai.speed)
  }

  updatePoliceCar(dt, v) {
    const ai = v.ai
    const p = this.game.player
    const target = p.inCar && this.playerVehicle ? this.playerVehicle.pos : p.pos
    const dx = target.x - v.pos.x
    const dz = target.z - v.pos.z
    const dist = Math.hypot(dx, dz)
    const desiredYaw = Math.atan2(dx, dz)
    const diff = Math.abs(((desiredYaw - v.yaw + Math.PI) % (Math.PI * 2)) - Math.PI)
    if (dist < 18) {
      ai.speed = damp(ai.speed, 0, 3, dt)
    } else {
      ai.speed = damp(ai.speed, diff > 0.7 ? 6 : 17, 1.5, dt)
    }
    v.yaw = angleLerp(v.yaw, desiredYaw, Math.min(1, dt * 2.4))
    v.pos.x += Math.sin(v.yaw) * ai.speed * dt
    v.pos.z += Math.cos(v.yaw) * ai.speed * dt
    this.world.resolveCircle(v.pos, 1.2)
    v.speed = ai.speed
    v.vel.set(Math.sin(v.yaw) * ai.speed, 0, Math.cos(v.yaw) * ai.speed)
    ai.stopped = dist < 20
  }

  updateVisual(dt, v, isPlayer = false) {
    v.group.position.copy(v.pos)
    v.group.rotation.y = v.yaw
    const spin = (v.speed || 0) * dt / 0.34
    for (const w of v.wheels) {
      w.tyre.rotation.x += spin
      if (w.front) w.pivot.rotation.y = v.steer * 0.5
    }
    // brake lights
    const braking = isPlayer ? this.game.input.brake > 0 : v.ai && v.ai.speed < 3
    if (v.tailMat) v.tailMat.emissiveIntensity = braking ? 4 : 1.2
    // siren blinking
    if (v.sirenMats) {
      v.sirenPhase += dt * 7
      const on = Math.sin(v.sirenPhase) > 0
      v.sirenMats.red.emissiveIntensity = on ? 4 : 0.6
      v.sirenMats.blue.emissiveIntensity = on ? 0.6 : 4
    }
    // smoke damage
    if (v.hp < v.maxHp * 0.35 && !v.destroyed) {
      v.damageSmoke -= dt
      if (v.damageSmoke <= 0) {
        v.damageSmoke = 0.18
        this.game.effects.puff(new THREE.Vector3(v.pos.x + (Math.random() - .5), 0.9, v.pos.z + (Math.random() - .5)), 0x2a2a2a, 0.5)
      }
    }
  }

  collideVehicles(dt) {
    const pv = this.playerVehicle
    if (!pv) return
    for (const v of this.vehicles) {
      if (v === pv || v.destroyed) continue
      const dx = v.pos.x - pv.pos.x
      const dz = v.pos.z - pv.pos.z
      const d = Math.hypot(dx, dz)
      const minD = 2.6
      if (d > 0.001 && d < minD) {
        const nx = dx / d, nz = dz / d
        const overlap = minD - d
        v.pos.x += nx * overlap * 0.5
        v.pos.z += nz * overlap * 0.5
        pv.pos.x -= nx * overlap * 0.5
        pv.pos.z -= nz * overlap * 0.5
        const rel = pv.vel.length()
        if (rel > 8) {
          this.damageVehicle(v, rel * 0.8)
          this.damageVehicle(pv, rel * 0.45)
          pv.vel.multiplyScalar(0.55)
          pv.speed *= 0.55
          this.game.effects.burst(new THREE.Vector3(pv.pos.x, 0.7, pv.pos.z), 8, 0xffc070, 4, 0.4, -10)
          this.game.audio.crash(rel / 20)
          this.game.player.takeDamage(rel * 0.15, 'crash', true)
        }
        if (v.ai) v.ai.speed *= 0.3
      }
    }
  }

  damageVehicle(v, amount) {
    if (v.destroyed) return
    v.hp -= amount
    if (v.hp <= 0 && !v.destroyed) this.explodeVehicle(v)
  }

  explodeVehicle(v) {
    v.destroyed = true
    v.hp = 0
    const pos = new THREE.Vector3(v.pos.x, 0.8, v.pos.z)
    this.game.effects.explosion(pos)
    this.game.effects.shake = Math.max(this.game.effects.shake, 0.8)
    v.paint = null
    v.group.traverse(o => {
      if (o.isMesh && o.material && o.material.color && o !== v.proxy) {
        o.material = o.material.clone()
        o.material.color.setHex(0x171614)
        if (o.material.emissive) o.material.emissiveIntensity = 0
      }
    })
    v.group.rotation.z = (Math.random() - .5) * 0.08
    if (v === this.playerVehicle) {
      this.game.player.takeDamage(55, 'explosion')
      this.playerVehicle = null
      this.game.player.inCar = false
      this.game.player.group.visible = true
      this.game.player.pos.set(v.pos.x + 2, 0, v.pos.z + 2)
      this.game.hud.setDriving(false)
    }
    if (v.ai && v.ai.mode === 'police') this.game.police.onUnitDestroyed(v)
    this.game.addWanted(1, 'destroyed a vehicle')
  }

  maintainTraffic(dt) {
    this.spawnTimer -= dt
    if (this.spawnTimer > 0) return
    this.spawnTimer = 2
    const traffic = this.vehicles.filter(v => v.traffic && v.ai && !v.destroyed)
    if (traffic.length < 11) this.spawnTraffic()
    // remove distant wrecks occasionally
    const p = this.game.player
    for (const v of this.vehicles) {
      if (v.destroyed && v.pos.distanceTo(p.pos) > 160 && v !== this.playerVehicle) {
        v.pos.y = -50
        v.group.visible = false
      }
    }
  }

  nearestPoliceDist(pos) {
    let best = Infinity
    for (const v of this.vehicles) {
      if (v.isPolice && !v.destroyed) best = Math.min(best, v.pos.distanceTo(pos))
    }
    return best
  }
}

