import * as THREE from 'three'
import { buildHuman, buildPistol } from './character.js'

const _v = new THREE.Vector3()

function rand(a, b) { return a + Math.random() * (b - a) }
function damp(a, b, l, dt) { return a + (b - a) * (1 - Math.exp(-l * dt)) }

export class Actor {
  constructor(game, opts = {}) {
    this.game = game
    this.kind = opts.kind ?? 'civilian'
    this.hostile = opts.hostile ?? false
    this.maxHp = opts.hp ?? (this.kind === 'cop' ? 90 : this.kind === 'gang' ? 70 : 32)
    this.hp = this.maxHp
    this.dead = false
    this.deadTime = 0
    this.pos = new THREE.Vector3(opts.x ?? 0, 0, opts.z ?? 0)
    this.yaw = opts.yaw ?? Math.random() * Math.PI * 2
    this.speed = 0
    this.phase = Math.random() * Math.PI * 2
    this.fleeTime = 0
    this.fireCooldown = rand(0.4, 1.4)
    this.hitFlash = 0
    this.marker = null
    this.removeMe = false
    this.faction = opts.faction ?? (this.kind === 'cop' ? 'cop' : this.kind === 'gang' ? 'gang' : 'civ')

    const uniform = this.faction === 'cop'
    const c = buildHuman({
      skin: opts.skin,
      shirt: uniform ? 0x1b2c46 : opts.shirt,
      pants: uniform ? 0x141c27 : opts.pants,
      shoe: uniform ? 0x0d0f12 : opts.shoe,
      sunglasses: uniform ? true : (opts.sunglasses ?? Math.random() < 0.16),
      hat: opts.hat ?? false,
      scale: opts.scale
    })
    this.char = c
    this.group = c.group
    this.group.position.copy(this.pos)
    this.group.rotation.y = this.yaw
    this.group.traverse(o => { if (o.isMesh) { o.castShadow = true } })
    game.scene.add(this.group)

    if (this.faction === 'cop') {
      const badge = new THREE.Mesh(
        new THREE.BoxGeometry(0.12, 0.12, 0.02),
        new THREE.MeshStandardMaterial({ color: 0xd6b24a, metalness: .9, roughness: .3 })
      )
      badge.position.set(-0.16, 1.35, 0.14)
      this.group.add(badge)
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.15, 0.08, 12), new THREE.MeshStandardMaterial({ color: 0x101826, roughness: .8 }))
      cap.position.y = 1.75
      const brim = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.02, 0.1), new THREE.MeshStandardMaterial({ color: 0x0a1018 }))
      brim.position.set(0, 1.72, 0.12)
      this.group.add(cap, brim)
    }

    // weapon for hostile actors
    if (this.hostile) {
      const gun = buildPistol()
      gun.position.set(0, -0.58, 0.06)
      c.parts.armR.add(gun)
      this.gun = gun
    }

    // hit proxy (invisible sphere)
    const proxy = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 8, 6),
      new THREE.MeshBasicMaterial({ visible: false })
    )
    proxy.position.y = 1.05
    proxy.userData = { type: 'actor', ref: this }
    proxy.visible = false
    this.proxy = proxy
    this.group.add(proxy)

    this.walkPhase = Math.random() * Math.PI * 2
  }

  setMarker(color = 0xff3b30) {
    if (this.marker) this.group.remove(this.marker)
    const m = new THREE.Group()
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.34, 4), new THREE.MeshBasicMaterial({ color }))
    cone.rotation.x = Math.PI
    cone.position.y = 2.35
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.32, 0.035, 6, 18), new THREE.MeshBasicMaterial({ color }))
    ring.rotation.x = Math.PI / 2
    ring.position.y = 0.06
    m.add(cone, ring)
    m.userData.spin = 0
    this.group.add(m)
    this.marker = m
  }

  assignPath(blocks) {
    const b = blocks[Math.floor(Math.random() * blocks.length)]
    const half = b.w / 2 - 3
    const halfD = b.d / 2 - 3
    const corners = [
      { x: b.x - half, z: b.z - halfD },
      { x: b.x + half, z: b.z - halfD },
      { x: b.x + half, z: b.z + halfD },
      { x: b.x - half, z: b.z + halfD }
    ]
    const start = Math.floor(Math.random() * 4)
    this.path = []
    for (let i = 0; i < 4; i++) this.path.push(corners[(start + i) % 4])
    this.pathIndex = 0
    this.pos.set(this.path[0].x + rand(-1.5, 1.5), 0, this.path[0].z + rand(-1.5, 1.5))
    this.yaw = Math.random() * Math.PI * 2
    this.group.position.copy(this.pos)
  }

  takeDamage(dmg, hitPoint, byPlayer = false) {
    if (this.dead) return
    this.hp -= dmg
    this.hitFlash = 0.12
    this.char.body.traverse(o => {
      if (o.isMesh && o.material && o.material.emissive) {
        o.material.emissive = new THREE.Color(0xff2211)
        o.material.emissiveIntensity = 0.7
      }
    })
    if (this.game.audio) this.game.audio.hitFlesh()
    if (this.hp <= 0) this.die(byPlayer)
    else {
      this.fleeTime = 8
      if (this.kind === 'civilian' && byPlayer) this.game.addWanted(1, 'assault')
    }
  }

  die(byPlayer) {
    if (this.dead) return
    this.dead = true
    this.deadTime = 0
    this.hp = 0
    this.group.rotation.z = Math.PI / 2
    this.group.position.y = 0.12
    if (this.marker) this.marker.visible = false
    // blood pool
    const pool = new THREE.Mesh(
      new THREE.CircleGeometry(0.7, 16),
      new THREE.MeshBasicMaterial({ color: 0x3d0a0a, transparent: true, opacity: 0.55 })
    )
    pool.rotation.x = -Math.PI / 2
    pool.position.set(this.pos.x, 0.34, this.pos.z)
    this.game.scene.add(pool)
    this.pool = pool
    if (byPlayer && this.kind === 'civilian') this.game.addWanted(2, 'murder')
    if (this.kind === 'gang' && this.game.missions) this.game.missions.onActorKilled(this)
    if (this.faction === 'cop' && this.game.police) this.game.police.onOfficerDown(this)
  }

  update(dt) {
    if (this.dead) {
      this.deadTime += dt
      if (this.deadTime > 8) {
        this.group.visible = false
        if (this.pool) this.pool.material.opacity = Math.min(0.55, Math.max(0, 0.55 - (this.deadTime - 8) * 0.2))
      }
      if (this.deadTime > 14 && !this.removeMe) {
        this.removeMe = true
        this.game.scene.remove(this.group)
        if (this.pool) this.game.scene.remove(this.pool)
      }
      return
    }

    if (this.hitFlash > 0) {
      this.hitFlash -= dt
      if (this.hitFlash <= 0) {
        this.char.body.traverse(o => {
          if (o.isMesh && o.material && o.material.emissive) o.material.emissiveIntensity = 0
        })
      }
    }

    if (this.marker) {
      this.marker.rotation.y += dt * 2
      this.marker.position.y = Math.sin(performance.now() * 0.003) * 0.06
    }

    const player = this.game.player
    const dist = player ? this.pos.distanceTo(player.pos) : 999

    // gunshot panic
    if (this.game.lastGunshot && performance.now() - this.game.lastGunshot < 900 && this.kind === 'civilian') {
      if (dist < 26) this.fleeTime = Math.max(this.fleeTime, 5)
    }

    if (this.faction === 'cop' && this.game.wanted === 0 && !this.forceHostile) {
      // cops idle after chase
    }

    if (this.hostile || (this.faction === 'cop' && this.game.wanted > 0)) {
      this.updateCombat(dt, dist)
    } else if (this.fleeTime > 0) {
      this.fleeTime -= dt
      this.updateFlee(dt, player)
    } else if (this.path) {
      this.updateWalk(dt)
    } else {
      this.speed = damp(this.speed, 0, 8, dt)
      this.animate(dt)
    }

    this.group.position.copy(this.pos)
    this.group.rotation.y = this.yaw
  }

  updateWalk(dt) {
    if (!this.path) return
    const target = this.path[this.pathIndex]
    const dx = target.x - this.pos.x
    const dz = target.z - this.pos.z
    const d = Math.hypot(dx, dz)
    if (d < 1.4) {
      this.pathIndex = (this.pathIndex + 1) % this.path.length
      if (Math.random() < 0.12) this.idle = rand(1, 3)
    }
    if (this.idle > 0) {
      this.idle -= dt
      this.speed = damp(this.speed, 0, 8, dt)
    } else {
      const speed = 1.15
      this.speed = damp(this.speed, speed, 4, dt)
      const desired = Math.atan2(dx, dz)
      this.yaw = dampAngle(this.yaw, desired, 6, dt)
      this.pos.x += Math.sin(this.yaw) * this.speed * dt
      this.pos.z += Math.cos(this.yaw) * this.speed * dt
    }
    this.animate(dt)
  }

  updateFlee(dt, player) {
    if (!player) return
    const dx = this.pos.x - player.pos.x
    const dz = this.pos.z - player.pos.z
    const d = Math.hypot(dx, dz) || 1
    const speed = this.fleeTime > 0 ? 4.8 : 0
    this.speed = damp(this.speed, speed, 5, dt)
    this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 8, dt)
    this.pos.x += (dx / d) * this.speed * dt
    this.pos.z += (dz / d) * this.speed * dt
    this.game.world.resolveCircle(this.pos, 0.45)
    this.animate(dt)
  }

  updateCombat(dt, dist) {
    const player = this.game.player
    if (!player) return
    const dx = player.pos.x - this.pos.x
    const dz = player.pos.z - this.pos.z
    const desired = Math.atan2(dx, dz)
    this.yaw = dampAngle(this.yaw, desired, 10, dt)
    // move toward if far, strafe if close
    const speed = this.kind === 'gang' ? 2.1 : 2.8
    if (dist > (this.kind === 'cop' ? 13 : 16)) {
      this.speed = damp(this.speed, speed, 4, dt)
      this.pos.x += Math.sin(this.yaw) * this.speed * dt
      this.pos.z += Math.cos(this.yaw) * this.speed * dt
      this.game.world.resolveCircle(this.pos, 0.45)
    } else if (dist < 6) {
      this.speed = damp(this.speed, -1.2, 3, dt)
      this.pos.x += Math.sin(this.yaw) * this.speed * dt
      this.pos.z += Math.cos(this.yaw) * this.speed * dt
    } else {
      this.speed = damp(this.speed, 0, 6, dt)
    }

    // shoot
    this.fireCooldown -= dt
    const eye = _v.set(this.pos.x, 1.5, this.pos.z)
    const seen = dist < 42 && !this.game.world.lineBlocked(eye, new THREE.Vector3(player.pos.x, 1.2, player.pos.z))
    if (seen && this.fireCooldown <= 0 && this.game.state === 'playing') {
      this.fireCooldown = rand(0.9, 1.7)
      const from = new THREE.Vector3(this.pos.x, 1.35, this.pos.z)
      const to = new THREE.Vector3(player.pos.x, 1.1, player.pos.z)
      const miss = rand(-0.5, 0.5)
      to.x += miss; to.z += rand(-0.5, 0.5)
      this.game.effects.tracer(from, to)
      this.game.effects.flash(from, 0.5, 0.06)
      this.game.audio.gunshot('pistol')
      this.game.lastGunshot = performance.now()
      if (Math.random() < 0.55) player.takeDamage(rand(5, 10), 'gunfire')
      this.aimTime = 0.4
    }
    if (this.aimTime > 0) this.aimTime -= dt
    this.animate(dt, this.aimTime > 0)
  }

  animate(dt, aiming = false) {
    const parts = this.char.parts
    this.walkPhase += this.speed * dt * 2.6
    const moving = Math.abs(this.speed) > 0.2
    const swing = Math.sin(this.walkPhase)
    const amp = Math.min(0.75, Math.abs(this.speed) * 0.18)
    const targetLegL = moving ? swing * amp : 0
    const targetLegR = moving ? -swing * amp : 0
    parts.legL.rotation.x = damp(parts.legL.rotation.x, targetLegL, 14, dt)
    parts.legR.rotation.x = damp(parts.legR.rotation.x, targetLegR, 14, dt)
    const targetArmL = aiming ? -1.35 : (moving ? -swing * amp * 0.8 : 0)
    const targetArmR = aiming ? -1.5 : (moving ? swing * amp * 0.8 : 0)
    parts.armL.rotation.x = damp(parts.armL.rotation.x, targetArmL, 12, dt)
    parts.armR.rotation.x = damp(parts.armR.rotation.x, targetArmR, 12, dt)
    parts.body.position.y = moving ? Math.abs(Math.sin(this.walkPhase * 2)) * 0.025 : Math.sin(performance.now() * 0.0016) * 0.006
    parts.torso.rotation.x = moving ? Math.min(0.12, Math.abs(this.speed) * 0.02) : 0
    if (aiming) {
      parts.armL.rotation.y = 0.35
      parts.armR.rotation.y = -0.15
    }
  }

  dispose() {
    this.game.scene.remove(this.group)
    if (this.pool) this.game.scene.remove(this.pool)
    this.removeMe = true
  }
}

function dampAngle(a, b, l, dt) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI
  if (d < -Math.PI) d += Math.PI * 2
  return a + d * (1 - Math.exp(-l * dt))
}

export class PedSystem {
  constructor(game) {
    this.game = game
    this.actors = []
    this.civilians = []
    this.maxCivilians = 18
    this.spawnTimer = 0
  }

  start() {
    for (let i = 0; i < this.maxCivilians; i++) this.spawnCivilian()
  }

  spawnCivilian() {
    const a = new Actor(this.game, { kind: 'civilian', x: 0, z: 0 })
    a.assignPath(this.game.world.blocks)
    this.actors.push(a)
    this.civilians.push(a)
    return a
  }

  spawnGang(x, z, count = 3) {
    const list = []
    for (let i = 0; i < count; i++) {
      const ang = (i / count) * Math.PI * 2
      const px = x + Math.cos(ang) * rand(2, 5)
      const pz = z + Math.sin(ang) * rand(2, 5)
      const a = new Actor(this.game, { kind: 'gang', hostile: true, x: px, z: pz, hp: 75, shirt: 0x5a1520, pants: 0x1b1d22 })
      a.setMarker(0xff3b30)
      this.actors.push(a)
      list.push(a)
    }
    return list
  }

  spawnCop(x, z, forceHostile = false) {
    const a = new Actor(this.game, { kind: 'cop', hostile: true, x, z, hp: 95, faction: 'cop' })
    a.forceHostile = forceHostile
    this.actors.push(a)
    return a
  }

  update(dt) {
    for (const a of this.actors) a.update(dt)
    // car hits
    const pv = this.game.vehicles?.playerVehicle
    if (pv && Math.abs(pv.speed) > 4 && !pv.destroyed) {
      for (const a of this.actors) {
        if (a.dead) continue
        const d = Math.hypot(a.pos.x - pv.pos.x, a.pos.z - pv.pos.z)
        if (d < 2.4) {
          a.takeDamage(60, null, true)
          a.stagger = new THREE.Vector3(pv.vel.x * 0.5, 0, pv.vel.z * 0.5)
          pv.vel.multiplyScalar(0.92)
          this.game.effects.burst(new THREE.Vector3(a.pos.x, 1, a.pos.z), 8, 0xaa1f1f, 3, 0.4, -8)
          this.game.audio.crash(0.6)
          this.game.addWanted(2, 'hit and run')
        }
      }
    }
    // cleanup and respawn
    this.actors = this.actors.filter(a => !a.removeMe)
    this.civilians = this.civilians.filter(a => !a.removeMe && !a.dead)
    this.spawnTimer -= dt
    if (this.spawnTimer <= 0 && this.civilians.length < this.maxCivilians) {
      this.spawnTimer = 3
      this.spawnCivilian()
    }
  }

  clearGang() {
    for (const a of this.actors) if (a.kind === 'gang' && !a.dead) a.dispose()
  }
}

import * as THREE from 'three'

function rand(a, b) { return a + Math.random() * (b - a) }

const GRID = [-160, -96, -32, 32, 96, 160]

export class PoliceSystem {
  constructor(game) {
    this.game = game
    this.wanted = 0
    this.units = []
    this.spawnTimer = 2
    this.evadeTimer = 0
    this.recentCrime = 0
    this.totalCopsDown = 0
  }

  addWanted(n, reason = '') {
    const before = this.wanted
    this.wanted = Math.min(5, this.wanted + n)
    this.evadeTimer = 0
    this.recentCrime = 3
    this.spawnTimer = Math.min(this.spawnTimer, 0.6)
    if (this.wanted > before) {
      this.game.hud.setWanted(this.wanted, true)
      if (this.game.audio) {
        if (before === 0) this.game.audio.sirenGain && this.game.audio.tone(720, 0.3, 0.05, 'square', 120)
      }
      if (reason && this.wanted >= 2) this.game.hud.notify(`WANTED: ${reason}`, '#ffb4a0')
    }
  }

  clearWanted() {
    this.wanted = 0
    this.recentCrime = 0
    this.evadeTimer = 0
    this.game.hud.setWanted(0)
    for (const u of this.units) u.retiring = true
  }

  activeUnits() {
    return this.units.filter(u => !u.dead)
  }

  update(dt) {
    if (this.game.state !== 'playing') return
    if (this.recentCrime > 0) this.recentCrime -= dt

    if (this.wanted > 0) {
      // maintain units
      this.spawnTimer -= dt
      const maxUnits = Math.min(4, Math.ceil(this.wanted / 1.4))
      if (this.spawnTimer <= 0 && this.activeUnits().length < maxUnits) {
        this.spawnUnit()
        this.spawnTimer = rand(3.5, 5.5)
      }
    }

    let nearest = Infinity
    for (const u of this.units) {
      if (u.dead) continue
      const car = u.car
      const d = car.pos.distanceTo(this.game.player.pos)
      nearest = Math.min(nearest, d)

      if (!u.deployed) {
        const carAlive = !car.destroyed
        if (!carAlive) {
          u.dead = true
          for (const o of u.officers) o.forceHostile = true
          continue
        }
        if (d < 26 || car.ai.stopped || car.speed < 1.5) {
          this.deployOfficers(u)
        }
      } else {
        // if all officers down and wanted is low, retire the car
        const alive = u.officers.filter(o => !o.dead && !o.removeMe)
        if (!alive.length) {
          u.dead = true
          car.ai = null
          car.driver = null
        }
      }

      if (u.retiring) {
        u.retireTimer = (u.retireTimer || 0) + dt
      }
    }

    // cleanup units
    this.units = this.units.filter(u => {
      if (u.dead) {
        if (u.car && !u.car.destroyed) {
          u.car.ai = null
          u.car.driver = null
        }
        return false
      }
      if (u.retiring) {
        if (u.car && !u.car.destroyed && (u.car.pos.distanceTo(this.game.player.pos) > 70 || u.retireTimer > 12)) {
          u.car.pos.y = -50
          u.car.group.visible = false
          u.car.destroyed = true
        }
        for (const o of u.officers) {
          if (!o.dead && (o.pos.distanceTo(this.game.player.pos) > 45 || u.retireTimer > 12)) o.dispose()
        }
        if (u.retireTimer > 12) return false
      }
      return true
    })

    // evade logic
    if (this.wanted > 0) {
      const seen = nearest < 58
      if (seen) this.evadeTimer = 0
      else {
        this.evadeTimer += dt
        if (this.evadeTimer > 9 && this.recentCrime <= 0) {
          this.wanted = Math.max(0, this.wanted - 1)
          this.game.hud.setWanted(this.wanted, true)
          this.game.hud.notify(this.wanted > 0 ? 'You lost a wanted star' : 'You lost the cops', '#9fd8ff')
          this.evadeTimer = 3
          if (this.wanted === 0) {
            for (const u of this.units) u.retiring = true
          }
        }
      }
    }

    // update cops' siren audio distance
    this.nearestDist = nearest
  }

  spawnUnit() {
    const p = this.game.player
    const angle = Math.random() * Math.PI * 2
    const dist = rand(70, 100)
    let x = p.pos.x + Math.cos(angle) * dist
    let z = p.pos.z + Math.sin(angle) * dist
    // snap to nearest road
    const gx = GRID.reduce((a, b) => Math.abs(b - x) < Math.abs(a - x) ? b : a, GRID[0])
    const gz = GRID.reduce((a, b) => Math.abs(b - z) < Math.abs(a - z) ? b : a, GRID[0])
    if (Math.abs(x - gx) < Math.abs(z - gz)) x = gx
    else z = gz
    x = Math.max(-160, Math.min(160, x))
    z = Math.max(-160, Math.min(160, z))
    // keep a little away from the player's exact spot
    if (Math.hypot(x - p.pos.x, z - p.pos.z) < 40) return
    const yaw = Math.atan2(p.pos.x - x, p.pos.z - z)
    const car = this.game.vehicles.addVehicle('police', 0xd9dde2, x, z, yaw, { driver: 'ai', hp: 220 })
    car.ai = { mode: 'police', speed: 2 }
    car.isPolice = true
    const unit = { car, officers: [], deployed: false, dead: false, retiring: false }
    this.units.push(unit)
    this.game.hud.notify('LSPD units responding', '#9fc9ff')
  }

  deployOfficers(u) {
    u.deployed = true
    u.car.ai.stopped = true
    const car = u.car
    const fwd = new THREE.Vector3(Math.sin(car.yaw), 0, Math.cos(car.yaw))
    const right = new THREE.Vector3(fwd.z, 0, -fwd.x)
    for (const s of [-1, 1]) {
      const pos = car.pos.clone().addScaledVector(right, s * 1.7).addScaledVector(fwd, 0.6)
      const cop = this.game.peds.spawnCop(pos.x, pos.z, true)
      cop.setMarker(0x4d9bff)
      u.officers.push(cop)
    }
  }

  onOfficerDown(actor) {
    this.totalCopsDown++
    this.game.addWanted(2, 'cop killer')
    for (const u of this.units) {
      u.officers = u.officers.filter(o => o !== actor)
    }
  }

  onUnitDestroyed(car) {
    for (const u of this.units) {
      if (u.car === car) u.dead = true
    }
  }

  reset() {
    this.wanted = 0
    this.evadeTimer = 0
    this.game.hud.setWanted(0)
    for (const u of this.units) {
      if (u.car && !u.car.destroyed) {
        u.car.driver = null
        u.car.ai = null
      }
      for (const o of u.officers) if (!o.dead) o.dispose()
    }
    this.units = []
  }
}

import * as THREE from 'three'

const GRID = [-160, -96, -32, 32, 96, 160]

function rand(a, b) { return a + Math.random() * (b - a) }

function labelTexture(text, color = '#ffd76a') {
  const c = document.createElement('canvas')
  c.width = c.height = 128
  const ctx = c.getContext('2d')
  ctx.clearRect(0, 0, 128, 128)
  ctx.beginPath()
  ctx.arc(64, 64, 54, 0, Math.PI * 2)
  ctx.fillStyle = 'rgba(10,10,12,0.72)'
  ctx.fill()
  ctx.lineWidth = 6
  ctx.strokeStyle = color
  ctx.stroke()
  ctx.fillStyle = color
  ctx.font = 'bold 72px Arial Black, Arial'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.fillText(text, 64, 70)
  const t = new THREE.CanvasTexture(c)
  t.colorSpace = THREE.SRGBColorSpace
  return t
}

class WorldMarker {
  constructor(scene, letter = 'M', color = 0xffc84a) {
    this.scene = scene
    this.group = new THREE.Group()
    this.group.visible = false
    const beamMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.22, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending })
    this.beam = new THREE.Mesh(new THREE.CylinderGeometry(1.35, 1.35, 9, 24, 1, true), beamMat)
    this.beam.position.y = 4.5
    this.ring = new THREE.Mesh(new THREE.TorusGeometry(1.5, 0.06, 6, 32), new THREE.MeshBasicMaterial({ color }))
    this.ring.rotation.x = Math.PI / 2
    this.ring.position.y = 0.12
    this.sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: labelTexture(letter, '#' + new THREE.Color(color).getHexString()), transparent: true, depthTest: false, depthWrite: false }))
    this.sprite.scale.set(1.7, 1.7, 1)
    this.sprite.position.y = 3.1
    this.group.add(this.beam, this.ring, this.sprite)
    this.scene.add(this.group)
    this.time = 0
  }
  setText(letter, color) {
    this.sprite.material.map.dispose()
    this.sprite.material.map = labelTexture(letter, '#' + new THREE.Color(color).getHexString())
    this.sprite.material.needsUpdate = true
    this.beam.material.color.setHex(color)
    this.ring.material.color.setHex(color)
  }
  setPosition(pos) { this.group.position.set(pos.x, 0, pos.z) }
  setVisible(v) { this.group.visible = v }
  update(dt) {
    if (!this.group.visible) return
    this.time += dt
    this.sprite.material.opacity = 0.75 + Math.sin(this.time * 3) * 0.2
    this.sprite.position.y = 3.1 + Math.sin(this.time * 2) * 0.12
    this.ring.scale.setScalar(1 + Math.sin(this.time * 2.6) * 0.06)
    this.beam.material.opacity = 0.16 + Math.sin(this.time * 2) * 0.05
  }
}

export class MissionSystem {
  constructor(game) {
    this.game = game
    this.active = false
    this.mission = null
    this.stepIndex = -1
    this.missionTimer = 0
    this.startPos = new THREE.Vector3(43, 0, 84)
    this.startMarker = new WorldMarker(game.scene, 'M', 0xffc84a)
    this.startMarker.setPosition(this.startPos)
    this.startMarker.setVisible(true)
    this.objectiveMarker = new WorldMarker(game.scene, '!', 0x7dff9a)
    this.checkpointRings = []
    this.completed = 0
    this.failTimer = 0
    this.cooloff = 0
    this.missionFactories = [
      () => this.repoMission(),
      () => this.sweepMission(),
      () => this.raceMission(),
      () => this.getawayMission()
    ]
  }

  /* ------------------------------------------------------------- missions */
  repoMission() {
    const hero = this.game.vehicles.heroCar
    return {
      title: 'REPO MAN',
      brief: 'Simeon needs that red Banshee back. Grab it and bring it to the lockup.',
      reward: 650,
      steps: [
        { type: 'steal', vehicle: hero, label: 'Steal the red Banshee', radius: 5 },
        { type: 'deliver', vehicle: hero, pos: new THREE.Vector3(34, 0, 100), radius: 5.5, label: 'Deliver the Banshee to the lockup' }
      ]
    }
  }

  sweepMission() {
    const hideout = this.pickPoint(90, 140)
    return {
      title: 'STREET SWEEP',
      brief: 'A crew is muscling in on the block. Take out all three before they take you out.',
      reward: 900,
      steps: [
        { type: 'eliminate', pos: hideout, radius: 6, label: 'Reach the stash house' }
      ]
    }
  }

  raceMission() {
    const points = []
    const start = this.pickPoint(60, 110)
    points.push(start)
    let last = start
    for (let i = 0; i < 5; i++) {
      let p = this.pickPoint(55, 90)
      let tries = 0
      while (p.distanceTo(last) < 45 && tries++ < 20) p = this.pickPoint(55, 90)
      points.push(p)
      last = p
    }
    return {
      title: 'VINEWOOD RUN',
      brief: 'Hit every checkpoint before the clock runs out. A fast car would help.',
      reward: 1200,
      steps: [
        { type: 'checkpoints', points, radius: 4.6, time: 85, label: 'Hit the checkpoints' }
      ]
    }
  }

  getawayMission() {
    return {
      title: 'HEAT',
      brief: 'The LSPD is on you. Stay free until the heat dies down.',
      reward: 1500,
      steps: [
        { type: 'evade', time: 75, label: 'Lose the cops' }
      ]
    }
  }

  pickPoint(minFromPlayer = 60, maxFromPlayer = 120) {
    const p = this.game.player.pos
    for (let i = 0; i < 40; i++) {
      let x = rand(-140, 140)
      let z = rand(-140, 140)
      // put it near a sidewalk / road edge so it is reachable
      const gx = GRID.reduce((a, b) => Math.abs(b - x) < Math.abs(a - x) ? b : a, GRID[0])
      const gz = GRID.reduce((a, b) => Math.abs(b - z) < Math.abs(a - z) ? b : a, GRID[0])
      if (Math.abs(x - gx) < Math.abs(z - gz)) x = gx + 11
      else z = gz + 11
      const d = Math.hypot(x - p.x, z - p.z)
      if (d < minFromPlayer || d > maxFromPlayer) continue
      return new THREE.Vector3(x, 0, z)
    }
    return new THREE.Vector3(p.x + 60, 0, p.z + 40)
  }

  /* --------------------------------------------------------------- control */
  startMission() {
    if (this.active) return
    const factory = this.missionFactories[this.completed % this.missionFactories.length]
    const m = factory()
    this.mission = m
    this.active = true
    this.stepIndex = -1
    this.startMarker.setVisible(false)
    this.game.hud.setObjective(m.title, m.brief)
    this.game.hud.missionSplash(m.title, m.brief)
    this.game.audio.missionStart()
    this.game.hud.notify('MISSION STARTED', '#ffd76a')
    this.setStep(0)
  }

  setStep(i) {
    const m = this.mission
    this.stepIndex = i
    if (i >= m.steps.length) { this.completeMission(); return }
    const step = m.steps[i]
    this.clearCheckpointRings()
    if (step.type === 'eliminate') {
      if (!step.spawned) {
        step.spawned = true
        step.actors = this.game.peds.spawnGang(step.pos.x, step.pos.z, 3)
        for (const a of step.actors) a.setMarker(0xff3b30)
      }
    }
    if (step.type === 'checkpoints') {
      step.cpIndex = 0
      this.missionTimer = step.time
      step.rings = step.points.map(pt => {
        const ring = new THREE.Mesh(
          new THREE.TorusGeometry(step.radius, 0.12, 6, 28),
          new THREE.MeshBasicMaterial({ color: 0x74ff9a, transparent: true, opacity: 0.85 })
        )
        ring.rotation.x = Math.PI / 2
        ring.position.set(pt.x, 0.3, pt.z)
        this.game.scene.add(ring)
        this.checkpointRings.push(ring)
        return ring
      })
    }
    if (step.type === 'evade') {
      this.missionTimer = step.time
      this.game.police.addWanted(3, 'heat')
    }
    this.game.hud.setObjective(m.title, step.label)
  }

  update(dt) {
    this.startMarker.update(dt)
    this.objectiveMarker.update(dt)
    for (const r of this.checkpointRings) {
      r.rotation.z += dt * 1.4
      r.material.opacity = 0.6 + Math.sin(performance.now() * 0.004) * 0.25
    }
    if (this.cooloff > 0) this.cooloff -= dt
    if (!this.active) {
      this.startMarker.setVisible(this.cooloff <= 0)
      if (this.cooloff <= 0) {
        const p = this.game.player
        if (!p.inCar && p.pos.distanceTo(this.startPos) < 2.9) {
          this.startMission()
        }
      }
      this.game.hud.setRadarMarker({ x: this.startPos.x, z: this.startPos.z, color: '#ffc84a', type: 'mission' })
      return
    }

    const step = this.mission.steps[this.stepIndex]
    if (!step) return
    const player = this.game.player
    const pv = this.game.vehicles.playerVehicle

    let objectivePos = step.pos
    let letter = '!'
    let color = 0x7dff9a

    if (step.type === 'steal') {
      if (step.vehicle && step.vehicle.destroyed) { this.failMission('The target vehicle was destroyed'); return }
      if (step.vehicle) {
        objectivePos = step.vehicle.pos
        if (pv === step.vehicle) {
          this.game.hud.notify('Now deliver it to the lockup', '#7dff9a')
          this.setStep(this.stepIndex + 1)
        }
      }
    } else if (step.type === 'deliver') {
      objectivePos = step.pos
      letter = '$'
      if (step.vehicle && step.vehicle.destroyed) { this.failMission('You wrecked the delivery car'); return }
      if (pv === step.vehicle) {
        const d = Math.hypot(pv.pos.x - step.pos.x, pv.pos.z - step.pos.z)
        if (d < step.radius) {
          this.setStep(this.stepIndex + 1)
        }
      }
    } else if (step.type === 'eliminate') {
      if (!step.actors || step.actors.every(a => a.dead)) {
        this.setStep(this.stepIndex + 1)
        return
      }
      const alive = step.actors.filter(a => !a.dead)
      let nearest = alive[0]
      for (const a of alive) {
        if (a.pos.distanceTo(player.pos) < nearest.pos.distanceTo(player.pos)) nearest = a
      }
      objectivePos = nearest.pos
      letter = 'X'
      color = 0xff5a4a
      if (player.pos.distanceTo(step.pos) < step.radius && !step.announced) {
        step.announced = true
        this.game.hud.notify('Targets spotted — take them down!', '#ff9a8a')
      }
    } else if (step.type === 'checkpoints') {
      const pt = step.points[step.cpIndex]
      objectivePos = pt
      this.missionTimer -= dt
      if (this.missionTimer <= 0) { this.failMission('Out of time'); return }
      const d = Math.hypot(player.pos.x - pt.x, player.pos.z - pt.z)
      if (d < step.radius + (pv ? 1.5 : 0)) {
        const ring = step.rings[step.cpIndex]
        if (ring) ring.visible = false
        step.cpIndex++
        this.game.audio.tone(880, 0.14, 0.12, 'triangle')
        this.game.effects.burst(new THREE.Vector3(pt.x, 1, pt.z), 20, 0x8dffb0, 6, 0.6, -6)
        if (step.cpIndex >= step.points.length) {
          this.setStep(this.stepIndex + 1)
        } else {
          this.game.hud.notify(`Checkpoint ${step.cpIndex}/${step.points.length}`, '#8dffb0')
          this.game.hud.setObjective(this.mission.title, step.label, this.missionTimer)
        }
      }
      this.game.hud.setRadarMarker({ x: pt.x, z: pt.z, color: '#7dff9a', type: 'checkpoint' })
    } else if (step.type === 'evade') {
      this.missionTimer -= dt
      objectivePos = player.pos
      letter = '!'
      color = 0x7db7ff
      this.game.hud.setObjective(this.mission.title, step.label, this.missionTimer)
      if (this.game.police.wanted === 0) {
        this.setStep(this.stepIndex + 1)
      } else if (this.missionTimer <= 0) {
        this.failMission('The cops caught up with you')
      }
    }

    // marker + radar
    const marker = this.objectiveMarker
    if (objectivePos) {
      marker.setPosition(objectivePos)
      marker.setVisible(true)
      marker.setText(letter, color)
    }
    if (objectivePos) this.game.hud.setRadarMarker({ x: objectivePos.x, z: objectivePos.z, color: '#' + new THREE.Color(color).getHexString(), type: 'objective' })

    // distance readout
    if (this.stepIndex >= 0 && this.mission && this.mission.steps[this.stepIndex]) {
      const st = this.mission.steps[this.stepIndex]
      if (objectivePos && st.type !== 'evade' && st.type !== 'eliminate') {
        const dist = Math.round(Math.hypot(player.pos.x - objectivePos.x, player.pos.z - objectivePos.z))
        this.game.hud.setObjective(this.mission.title, `${st.label} · ${dist}m`, st.type === 'checkpoints' ? this.missionTimer : null)
      }
      if (st.type === 'deliver' && !pv) {
        this.game.hud.setObjective(this.mission.title, 'Get back in the delivery vehicle', null)
      }
    }

    // timer HUD
    if (step.type === 'checkpoints' || step.type === 'evade') this.game.hud.setTimer(this.missionTimer)
    else this.game.hud.setTimer(null)
  }

  onActorKilled(actor) {
    if (!this.active) return
    const step = this.mission?.steps[this.stepIndex]
    if (!step || step.type !== 'eliminate') return
    const alive = step.actors.filter(a => !a.dead)
    this.game.hud.notify(alive.length > 0 ? `${alive.length} targets left` : 'All targets down', '#ffb3a8')
  }

  notifyVehicleStolen(v) {
    if (!this.active) return
    const step = this.mission?.steps[this.stepIndex]
    if (step && step.type === 'steal' && step.vehicle === v) {
      this.game.hud.notify('Nice ride. Deliver it to the lockup.', '#7dff9a')
    }
  }

  completeMission() {
    const m = this.mission
    this.active = false
    this.objectiveMarker.setVisible(false)
    this.clearCheckpointRings()
    const reward = Math.round(m.reward * (1 + this.completed * 0.15))
    this.game.addMoney(reward)
    this.completed++
    this.game.hud.missionComplete(m.title, reward)
    this.game.audio.missionComplete()
    this.game.hud.setTimer(null)
    this.game.hud.setObjective(null, null)
    this.game.hud.setRadarMarker(null)
    this.cooloff = 4
    this.mission = null
    this.stepIndex = -1
    this.placeNextStart()
    // clear any mission gang markers
    this.game.police.evadeTimer = 0
  }

  failMission(reason) {
    if (!this.active) return
    this.active = false
    this.objectiveMarker.setVisible(false)
    this.clearCheckpointRings()
    this.game.hud.missionFailed(reason || 'Mission failed')
    this.game.audio.fail()
    this.game.hud.setTimer(null)
    this.game.hud.setObjective(null, null)
    this.game.hud.setRadarMarker(null)
    this.cooloff = 5
    const m = this.mission
    this.mission = null
    this.stepIndex = -1
    // cleanup gang
    if (m) {
      for (const st of m.steps) {
        if (st.actors) st.actors.forEach(a => { if (!a.dead) a.dispose() })
      }
      if (m.steps.some(s => s.type === 'evade')) this.game.police.clearWanted()
    }
    this.placeNextStart()
  }

  placeNextStart() {
    const p = this.game.player.pos
    const ang = Math.random() * Math.PI * 2
    let x = p.x + Math.cos(ang) * rand(8, 16)
    let z = p.z + Math.sin(ang) * rand(8, 16)
    const gx = GRID.reduce((a, b) => Math.abs(b - x) < Math.abs(a - x) ? b : a, GRID[0])
    const gz = GRID.reduce((a, b) => Math.abs(b - z) < Math.abs(a - z) ? b : a, GRID[0])
    if (Math.abs(x - gx) < Math.abs(z - gz)) x = gx + 11
    else z = gz + 11
    const pos = new THREE.Vector3(x, 0, z)
    this.game.world.resolveCircle(pos, 1.2)
    this.startPos.copy(pos)
    this.startMarker.setPosition(pos)
    this.startMarker.setText('M', 0xffc84a)
  }

  onPlayerDeath() {
    if (this.active) this.failMission('You were wasted')
  }

  clearCheckpointRings() {
    for (const r of this.checkpointRings) {
      this.game.scene.remove(r)
      r.geometry.dispose()
      r.material.dispose()
    }
    this.checkpointRings = []
  }

  forceStart() {
    if (!this.active && this.cooloff <= 0) this.startMission()
  }
}

:root {
  --gold: #f6c453;
  --gold-deep: #c8922a;
  --ink: #0c0b0a;
  --cream: #f2ead9;
  --danger: #ff5a4a;
  --green: #8dffb0;
  --hud: rgba(12, 12, 12, 0.62);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden;
  background: #0a0908; color: var(--cream);
  font-family: "Helvetica Neue", Arial, sans-serif;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
button { font-family: inherit; cursor: pointer; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene { position: absolute; inset: 0; }
#scene canvas { display: block; width: 100%; height: 100%; }

.fx-vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 3;
  background:
    radial-gradient(ellipse at center, rgba(0,0,0,0) 52%, rgba(0,0,0,0.32) 100%),
    linear-gradient(180deg, rgba(255,166,90,0.10), rgba(0,0,0,0) 22%, rgba(0,0,0,0.10) 100%);
  mix-blend-mode: normal;
}
.fx-grain {
  position: absolute; inset: 0; pointer-events: none; z-index: 4; opacity: .06;
  background-image: repeating-linear-gradient(0deg, rgba(255,255,255,.8) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}
#damage-flash {
  position: absolute; inset: 0; z-index: 5; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at center, rgba(255,0,0,0) 40%, rgba(180,0,0,0.65) 100%);
  transition: opacity .12s linear;
}

#ui { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
#ui button { pointer-events: auto; }

/* ------------------------------------------------------------- top right */
#hud-topright {
  position: absolute; top: calc(var(--safe-t) + 14px); right: calc(var(--safe-r) + 16px);
  display: flex; flex-direction: column; align-items: flex-end; gap: 6px;
  text-shadow: 0 2px 6px rgba(0,0,0,.8);
}
#money {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(26px, 3.4vw, 40px);
  letter-spacing: 1px;
  color: #9fe39a;
  -webkit-text-stroke: 1px rgba(0,0,0,.4);
}
#wanted { display: flex; gap: 2px; height: 22px; }
#wanted .star {
  font-size: 20px; color: rgba(255,255,255,.16);
  text-shadow: 0 0 6px rgba(0,0,0,.6);
  transition: color .2s, transform .2s;
}
#wanted .star.on { color: var(--gold); text-shadow: 0 0 10px rgba(246,196,83,.75); }
body.wanted-pulse #wanted .star.on { animation: starflash .45s ease-out; }
@keyframes starflash { 0% { transform: scale(1.35); color: #fff; } 100% { transform: scale(1); } }

#weapon {
  margin-top: 2px; display: flex; flex-direction: column; align-items: flex-end;
  background: linear-gradient(90deg, transparent, rgba(0,0,0,.5));
  padding: 5px 10px 5px 22px; border-right: 2px solid rgba(246,196,83,.55);
}
#weapon-name { font-size: 11px; letter-spacing: 3px; color: #d8d2c4; }
#ammo { font-family: Impact, "Arial Black", sans-serif; font-size: 22px; letter-spacing: 1px; color: #f4efe4; }
#ammo b { color: #fff; }
#ammo.low { color: var(--danger); }

/* --------------------------------------------------------------- objective */
#objective {
  position: absolute; top: calc(var(--safe-t) + 60px); left: calc(var(--safe-l) + 18px);
  max-width: 330px; padding: 9px 14px 10px 14px;
  background: linear-gradient(90deg, rgba(0,0,0,.62), rgba(0,0,0,.18));
  border-left: 3px solid var(--gold);
  backdrop-filter: blur(2px);
  animation: objIn .3s ease-out;
}
@keyframes objIn { from { opacity: 0; transform: translateX(-12px); } to { opacity: 1; transform: none; } }
#obj-title { font-size: 10px; letter-spacing: 3px; color: var(--gold); font-weight: 700; }
#obj-text { margin-top: 3px; font-size: 14px; line-height: 1.3; color: #f4efe4; text-shadow: 0 1px 4px #000; }

#timer {
  position: absolute; top: calc(var(--safe-t) + 16px); left: 50%; transform: translateX(-50%);
  font-family: Impact, "Arial Black", sans-serif; font-size: 30px; letter-spacing: 2px;
  color: #f5f0e4; background: rgba(0,0,0,.5); padding: 2px 18px 3px;
  border-top: 2px solid rgba(246,196,83,.6); border-bottom: 2px solid rgba(246,196,83,.6);
  text-shadow: 0 2px 8px #000;
}
#timer.hurry { color: #ff7a66; animation: hurry .6s steps(2) infinite; }
@keyframes hurry { 50% { opacity: .55; } }

/* ----------------------------------------------------------------- radar */
#bottomleft {
  position: absolute; left: calc(var(--safe-l) + 16px); bottom: calc(var(--safe-b) + 16px);
  display: flex; flex-direction: column; gap: 7px;
}
#radar-wrap {
  width: 184px; height: 184px; position: relative; border-radius: 50%;
  box-shadow: 0 6px 24px rgba(0,0,0,.55), 0 0 0 3px rgba(8,8,8,.82), 0 0 0 5px rgba(246,196,83,.22);
  overflow: hidden;
}
#radar { width: 100%; height: 100%; display: block; }
#bars { display: flex; flex-direction: column; gap: 4px; width: 184px; }
.bar { height: 9px; background: rgba(0,0,0,.65); border: 1px solid rgba(255,255,255,.18); overflow: hidden; }
.bar i { display: block; height: 100%; width: 100%; transition: width .18s linear; }
.bar.hp i { background: linear-gradient(90deg, #5ecf6b, #a8ec73); box-shadow: 0 0 12px rgba(120,240,120,.35); }
.bar.armor i { background: linear-gradient(90deg, #4c9be8, #7fd4ff); }
.bar.hp.low i { background: linear-gradient(90deg, #e0452f, #ff8a5e); }

/* -------------------------------------------------------------- speedometer */
#speedo {
  position: absolute; right: calc(var(--safe-r) + 26px); bottom: calc(var(--safe-b) + 24px);
  text-align: right; color: #f6f1e6; text-shadow: 0 2px 10px #000;
}
#speed-num { font-family: Impact, "Arial Black", sans-serif; font-size: 54px; line-height: .9; letter-spacing: 1px; }
.speed-meta { display: flex; justify-content: flex-end; gap: 8px; align-items: baseline; margin-top: 2px; }
.speed-meta small { font-size: 10px; letter-spacing: 4px; color: var(--gold); }
#gear { font-size: 13px; color: #d8d2c4; border: 1px solid rgba(255,255,255,.3); padding: 0 4px; }

/* --------------------------------------------------------------- crosshair */
#crosshair { position: absolute; left: 50%; top: 50%; width: 34px; height: 34px; transform: translate(-50%,-50%); }
#crosshair i { position: absolute; background: rgba(255,255,255,.85); box-shadow: 0 0 3px rgba(0,0,0,.9); }
#crosshair .ch-t { left: 16px; top: 0; width: 2px; height: 8px; }
#crosshair .ch-b { left: 16px; bottom: 0; width: 2px; height: 8px; }
#crosshair .ch-l { top: 16px; left: 0; width: 8px; height: 2px; }
#crosshair .ch-r { top: 16px; right: 0; width: 8px; height: 2px; }
#crosshair .ch-dot { left: 16px; top: 16px; width: 2px; height: 2px; border-radius: 50%; }
#crosshair.aim i { background: var(--gold); }

/* ----------------------------------------------------------------- prompt */
#prompt {
  position: absolute; left: 50%; bottom: 16%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px;
  background: rgba(8,8,8,.68); border: 1px solid rgba(255,255,255,.14);
  padding: 7px 16px 7px 7px; backdrop-filter: blur(4px);
  font-size: 12px; letter-spacing: 2px; color: #f2ead9;
}
#prompt b {
  display: grid; place-items: center; width: 28px; height: 28px;
  background: var(--cream); color: #111; font-size: 14px; border-radius: 3px;
}

/* ------------------------------------------------------------------ toasts */
#toasts {
  position: absolute; top: calc(var(--safe-t) + 88px); left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px; width: min(92vw, 460px);
}
.toast {
  background: rgba(10,10,10,.72); border-left: 2px solid var(--gold);
  padding: 6px 14px; font-size: 12px; letter-spacing: 1.6px; color: #f6f0e2;
  animation: toastIn .22s ease-out;
  text-shadow: 0 1px 4px #000;
}
.toast.out { opacity: 0; transform: translateY(-6px); transition: .4s; }
@keyframes toastIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ---------------------------------------------------------------- splash */
#mission-splash {
  position: absolute; z-index: 14; left: 0; right: 0; top: 22%;
  text-align: center; pointer-events: none;
  animation: splashIn .5s ease-out;
  text-shadow: 0 4px 24px rgba(0,0,0,.9);
}
#mission-splash.out { animation: splashOut .6s ease-in forwards; }
@keyframes splashIn { from { opacity: 0; transform: scale(.96) translateY(12px); } to { opacity: 1; transform: none; } }
@keyframes splashOut { to { opacity: 0; transform: translateY(-14px); } }
.splash-kicker { font-size: 11px; letter-spacing: 8px; color: var(--gold); }
#splash-title {
  font-family: Impact, "Arial Black", sans-serif; font-size: clamp(44px, 7vw, 84px);
  letter-spacing: 2px; line-height: .95; color: #fbf4e4;
  -webkit-text-stroke: 2px rgba(0,0,0,.35);
}
.splash-line { width: min(340px, 60vw); height: 2px; margin: 10px auto; background: linear-gradient(90deg, transparent, var(--gold), transparent); }
#splash-brief { max-width: 560px; margin: 0 auto; padding: 0 24px; font-size: 14px; line-height: 1.5; color: #e7dfd0; }

#mission-banner {
  position: absolute; z-index: 15; left: 0; right: 0; top: 36%;
  text-align: center; pointer-events: none; animation: splashIn .4s ease-out;
}
#banner-title {
  font-family: Impact, "Arial Black", sans-serif; font-size: clamp(36px, 6vw, 70px);
  letter-spacing: 3px; color: var(--gold); -webkit-text-stroke: 2px rgba(0,0,0,.4);
  text-shadow: 0 4px 30px rgba(0,0,0,.9);
}
#banner-sub { font-size: 16px; letter-spacing: 5px; color: #f8f2e6; margin-top: 4px; text-shadow: 0 2px 10px #000; }

/* ------------------------------------------------------------- mobile btns */
#mobile-controls { display: none; }
body.touch #mobile-controls { display: block; }

#joystick {
  position: absolute; left: calc(var(--safe-l) + 22px); bottom: calc(var(--safe-b) + 24px);
  width: 132px; height: 132px; border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, rgba(255,255,255,.07), rgba(0,0,0,.34) 70%);
  border: 1px solid rgba(255,255,255,.22);
  box-shadow: inset 0 0 30px rgba(0,0,0,.4);
  pointer-events: auto; touch-action: none;
}
#stick {
  position: absolute; left: 50%; top: 50%; width: 58px; height: 58px; border-radius: 50%;
  transform: translate(-50%,-50%);
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.42), rgba(255,255,255,.14) 60%, rgba(0,0,0,.25));
  border: 1px solid rgba(255,255,255,.4);
  box-shadow: 0 4px 14px rgba(0,0,0,.5);
}
#mobile-buttons { position: absolute; inset: 0; pointer-events: none; }
.mbtn {
  position: absolute; pointer-events: auto; touch-action: none;
  border-radius: 50%; border: 1px solid rgba(255,255,255,.3);
  background: radial-gradient(circle at 35% 28%, rgba(255,255,255,.22), rgba(20,20,20,.55) 65%);
  color: #f3ecdd; font-size: 11px; letter-spacing: 1.5px; font-weight: 700;
  text-shadow: 0 1px 4px #000; box-shadow: 0 4px 14px rgba(0,0,0,.45);
  backdrop-filter: blur(3px);
}
.mbtn:active, .mbtn.down { transform: scale(.94); background: radial-gradient(circle at 35% 28%, rgba(246,196,83,.55), rgba(30,20,5,.6) 70%); }
.mbtn.fire {
  right: calc(var(--safe-r) + 20px); bottom: calc(var(--safe-b) + 22px);
  width: 94px; height: 94px; font-size: 13px; letter-spacing: 2px;
  border-color: rgba(246,196,83,.6); color: #ffe6ad;
}
.mbtn.md {
  right: calc(var(--safe-r) + 128px); bottom: calc(var(--safe-b) + 30px);
  width: 62px; height: 62px;
}
.mbtn[data-action="car"] {
  right: calc(var(--safe-r) + 28px); bottom: calc(var(--safe-b) + 128px);
  width: 68px; height: 68px;
}
.mbtn.small {
  right: calc(var(--safe-r) + 116px); bottom: calc(var(--safe-b) + 104px);
  width: 54px; height: 54px; font-size: 9px;
}
.mbtn[data-action="reload"] { right: calc(var(--safe-r) + 178px); bottom: calc(var(--safe-b) + 52px); }

#pause-btn, #mute-btn {
  position: absolute; top: calc(var(--safe-t) + 12px);
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(10,10,10,.5); color: #e9e1d1; border: 1px solid rgba(255,255,255,.2);
  font-size: 11px; letter-spacing: 0; z-index: 20;
}
#pause-btn { left: calc(var(--safe-l) + 14px); }
#mute-btn { left: calc(var(--safe-l) + 54px); }
#pause-btn:hover, #mute-btn:hover { border-color: var(--gold); color: var(--gold); }

#hint {
  position: absolute; left: 50%; bottom: calc(var(--safe-b) + 10px); transform: translateX(-50%);
  font-size: 10px; letter-spacing: 2px; color: rgba(255,255,255,.5);
  text-shadow: 0 1px 4px #000; opacity: 1; transition: opacity 1s; white-space: nowrap;
}
#hint.gone { opacity: 0; }

/* ----------------------------------------------------------------- screens */
.screen {
  position: absolute; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center;
  background:
    radial-gradient(ellipse at 50% 120%, rgba(255,122,40,.22), transparent 60%),
    linear-gradient(180deg, rgba(6,7,10,.78), rgba(9,7,6,.92) 55%, rgba(4,4,4,.97));
  backdrop-filter: blur(2px);
  padding: 24px;
}
#start { background: linear-gradient(180deg, rgba(6,7,10,.55) 0%, rgba(8,7,6,.72) 60%, rgba(4,4,4,.95) 100%); }
.start-inner { width: min(920px, 94vw); text-align: center; }
.logo-wrap { transform: skewY(-1.2deg); }
.logo-kicker { font-size: clamp(13px, 1.6vw, 19px); letter-spacing: .62em; color: #d9cfba; text-indent: .62em; }
.logo-main {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(64px, 12vw, 148px); line-height: .88; letter-spacing: .015em;
  background: linear-gradient(180deg, #fff4d2 4%, #f6c453 42%, #b8761c 72%, #f4d58b 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 6px 22px rgba(0,0,0,.65));
  padding: 4px 0 10px;
}
.logo-sub { margin-top: 4px; font-size: clamp(9px, 1.2vw, 13px); letter-spacing: .55em; color: var(--gold); text-indent: .55em; }
.start-rule { width: min(540px, 82vw); height: 1px; margin: 20px auto; background: linear-gradient(90deg, transparent, rgba(246,196,83,.8), transparent); position: relative; }
.start-rule::after { content: "◆"; position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%); font-size: 9px; color: var(--gold); background: #0a0908; padding: 0 10px; }
.start-copy { font-size: clamp(12px, 1.4vw, 15px); line-height: 1.65; color: #d6cdbd; margin: 0 auto 22px; max-width: 620px; }
#play-btn, #resume-btn, #restart-btn {
  min-width: 260px; padding: 14px 34px;
  background: linear-gradient(180deg, #f8d170, #d99c2d);
  color: #1b1204; border: none; font-weight: 900; font-size: 14px; letter-spacing: 4px;
  box-shadow: 0 10px 30px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.6);
  transition: transform .15s, filter .15s;
  clip-path: polygon(3% 0, 100% 0, 97% 100%, 0 100%);
}
#play-btn:disabled { filter: grayscale(.6) brightness(.6); cursor: wait; }
#play-btn:not(:disabled):hover, #resume-btn:hover { transform: translateY(-2px); filter: brightness(1.08); }
#loading-bar { width: 260px; height: 3px; margin: 12px auto 0; background: rgba(255,255,255,.12); overflow: hidden; }
#loading-bar i { display: block; height: 100%; width: 0%; background: var(--gold); transition: width .3s; }
#loading-bar.done { opacity: 0; transition: opacity .6s; }
.controls-grid {
  margin: 26px auto 0; display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 12px 8px; max-width: 760px;
}
.controls-grid.touch-only { display: none; }
body.touch .controls-grid#controls-desktop { display: none; }
body.touch .controls-grid#controls-touch { display: grid; grid-template-columns: repeat(3, 1fr); }
.controls-grid div { display: flex; flex-direction: column; gap: 3px; }
.controls-grid b { font-size: 10px; letter-spacing: 2px; color: var(--gold); font-weight: 700; }
.controls-grid span { font-size: 10px; letter-spacing: .5px; color: rgba(232,224,209,.62); }
.start-foot { margin-top: 22px; font-size: 10px; letter-spacing: 2px; color: rgba(232,224,209,.35); }

/* pause */
.pause-inner { text-align: center; }
.pause-title {
  font-family: Impact, "Arial Black", sans-serif; font-size: clamp(54px, 9vw, 104px);
  letter-spacing: 4px; color: #f6eeda; margin: 4px 0 0;
  text-shadow: 0 6px 30px rgba(0,0,0,.8);
}
#resume-btn { margin-top: 8px; }
#restart-btn {
  display: block; margin: 14px auto 0; background: transparent; color: #cfc6b6;
  border: 1px solid rgba(255,255,255,.22); box-shadow: none; clip-path: none;
  font-size: 11px; letter-spacing: 3px; padding: 10px 22px; min-width: 220px;
}
#restart-btn:hover { border-color: var(--gold); color: var(--gold); }
.pause-stats { display: flex; justify-content: center; gap: clamp(28px, 6vw, 70px); margin: 26px 0 0; }
.pause-stats div { display: flex; flex-direction: column; gap: 4px; }
.pause-stats small { font-size: 9px; letter-spacing: 2px; color: rgba(232,224,209,.5); }
.pause-stats b { font-family: Impact, "Arial Black", sans-serif; font-size: 26px; color: var(--gold); font-weight: 400; }

/* wasted */
#wasted {
  background: radial-gradient(ellipse at center, rgba(70,0,0,.45), rgba(0,0,0,.9) 70%);
  z-index: 32;
}
.wasted-inner { text-align: center; }
.wasted-title {
  font-family: Impact, "Arial Black", sans-serif; font-size: clamp(72px, 15vw, 180px);
  letter-spacing: 6px; color: #a51f18;
  text-shadow: 0 0 40px rgba(255,60,40,.3), 0 8px 40px rgba(0,0,0,.9);
  animation: wastedIn .8s cubic-bezier(.2,.9,.2,1);
}
@keyframes wastedIn { from { transform: scale(1.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.wasted-sub { font-size: 13px; letter-spacing: 5px; color: rgba(255,210,200,.65); }

#rotate-hint {
  position: absolute; z-index: 40; top: calc(var(--safe-t) + 8px); left: 50%; transform: translateX(-50%);
  background: rgba(0,0,0,.7); color: #f1e8d8; font-size: 10px; letter-spacing: 2px;
  padding: 6px 14px; border: 1px solid rgba(246,196,83,.4); white-space: nowrap;
}

/* --------------------------------------------------------------- responsive */
@media (max-width: 820px), (max-height: 560px) {
  #radar-wrap { width: 132px; height: 132px; }
  #bars { width: 132px; }
  .bar { height: 7px; }
  #objective { max-width: 240px; padding: 7px 10px; }
  #obj-text { font-size: 12px; }
  #weapon { padding: 3px 8px 3px 16px; }
  #weapon-name { font-size: 9px; letter-spacing: 2px; }
  #ammo { font-size: 18px; }
  #speed-num { font-size: 40px; }
  #toasts { top: calc(var(--safe-t) + 70px); }
}

body.touch #bottomleft {
  top: calc(var(--safe-t) + 10px); bottom: auto;
  left: calc(var(--safe-l) + 12px);
}
body.touch #radar-wrap { width: 108px; height: 108px; }
body.touch #bars { width: 108px; }
body.touch .bar { height: 6px; }
body.touch #objective { top: calc(var(--safe-t) + 132px); left: calc(var(--safe-l) + 12px); max-width: min(52vw, 280px); }
body.touch #hud-topright { top: calc(var(--safe-t) + 12px); right: calc(var(--safe-r) + 12px); }
body.touch #money { font-size: 25px; }
body.touch #wanted { height: 16px; }
body.touch #wanted .star { font-size: 15px; }
body.touch #weapon-name { display: none; }
body.touch #weapon { padding: 2px 8px; }
body.touch #ammo { font-size: 16px; }
body.touch #speedo { bottom: calc(var(--safe-b) + 206px); right: calc(var(--safe-r) + 18px); }
body.touch #speed-num { font-size: 34px; }
body.touch #timer { top: calc(var(--safe-t) + 8px); font-size: 22px; padding: 1px 12px; }
body.touch #toasts { top: calc(var(--safe-t) + 60px); }
body.touch #prompt { bottom: 26%; }
body.touch #pause-btn, body.touch #mute-btn { top: calc(var(--safe-t) + 10px); }
body.touch #pause-btn { left: 50%; transform: translateX(-64px); }
body.touch #mute-btn { left: 50%; transform: translateX(26px); }
body.touch #hint { display: none; }
body.touch .screen { padding: 14px; }
body.touch .logo-main { font-size: clamp(52px, 15vw, 110px); }
body.touch .controls-grid { margin-top: 16px; }

@media (orientation: portrait) and (pointer: coarse) {
  #rotate-hint { display: block; }
  .start-copy { display: none; }
  .controls-grid { display: none !important; }
  .logo-main { font-size: 64px; }
  #play-btn { margin-top: 18px; }
}

/* keep HUD inside notches on phones in landscape */
body.touch #mobile-buttons .fire { right: calc(var(--safe-r) + 18px); }

export class HUD {
  constructor(game) {
    this.game = game
    const $ = id => document.getElementById(id)
    this.el = {
      money: $('money'),
      wanted: $('wanted'),
      weaponName: $('weapon-name'),
      ammoMag: $('ammo-mag'),
      ammoReserve: $('ammo-reserve'),
      ammo: $('ammo'),
      objective: $('objective'),
      objTitle: $('obj-title'),
      objText: $('obj-text'),
      timer: $('timer'),
      radar: $('radar'),
      hpfill: $('hpfill'),
      armorfill: $('armorfill'),
      hpbar: document.querySelector('.bar.hp'),
      speedo: $('speedo'),
      speedNum: $('speed-num'),
      gear: $('gear'),
      crosshair: $('crosshair'),
      prompt: $('prompt'),
      promptKey: $('prompt-key'),
      promptText: $('prompt-text'),
      toasts: $('toasts'),
      splash: $('mission-splash'),
      splashTitle: $('splash-title'),
      splashBrief: $('splash-brief'),
      banner: $('mission-banner'),
      bannerTitle: $('banner-title'),
      bannerSub: $('banner-sub'),
      damage: $('damage-flash'),
      wasted: $('wasted'),
      wastedSub: $('wasted-sub'),
      pause: $('pause'),
      hint: $('hint'),
      statMissions: $('stat-missions'),
      statMoney: $('stat-money'),
      statWanted: $('stat-wanted'),
      rotate: $('rotate-hint')
    }
    this.ctx = this.el.radar.getContext('2d')
    this.marker = null
    this.timerVal = null
    this.driving = false
    this.money = 0
    this.wanted = 0
    this.splashTimer = null
    this.bannerTimer = null
    this.promptShown = null
    this.lastRadar = 0
    this.touch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window

    // wanted stars
    this.stars = []
    for (let i = 0; i < 5; i++) {
      const s = document.createElement('span')
      s.className = 'star'
      s.textContent = '★'
      this.el.wanted.appendChild(s)
      this.stars.push(s)
    }

    if (this.touch) {
      const h = document.getElementById('hint')
      if (h) h.textContent = 'DRAG TO LOOK · STICK TO MOVE · TAP FIRE'
    } else {
      this.el.hint.textContent = 'WASD MOVE · MOUSE LOOK · F ENTER CAR · CLICK SHOOT · ESC PAUSE'
    }
  }

  setMoney(v) {
    this.money = v
    this.el.money.textContent = '$' + Math.max(0, Math.round(v)).toLocaleString('en-US')
    this.el.statMoney.textContent = this.el.money.textContent
  }

  setWanted(n, pulse = false) {
    this.wanted = n
    this.stars.forEach((s, i) => s.classList.toggle('on', i < n))
    this.el.statWanted.textContent = n > 0 ? '★'.repeat(n) : 'CLEAN'
    if (pulse && n > 0) {
      document.body.classList.add('wanted-pulse')
      clearTimeout(this.wantedTimer)
      this.wantedTimer = setTimeout(() => document.body.classList.remove('wanted-pulse'), 500)
    }
  }

  setObjective(title, text, timer) {
    if (!title) { this.el.objective.classList.add('hidden'); return }
    this.el.objective.classList.remove('hidden')
    if (this.el.objTitle.textContent !== title) this.el.objTitle.textContent = title
    if (this.el.objText.textContent !== text) this.el.objText.textContent = text
    if (timer !== undefined) this.setTimer(timer)
  }

  setTimer(sec) {
    if (sec === null || sec === undefined) {
      this.el.timer.classList.add('hidden')
      this.timerVal = null
      return
    }
    this.el.timer.classList.remove('hidden')
    const s = Math.max(0, Math.ceil(sec))
    const txt = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
    if (this.el.timer.textContent !== txt) this.el.timer.textContent = txt
    this.el.timer.classList.toggle('hurry', s <= 10)
  }

  setRadarMarker(m) { this.marker = m }

  setDriving(b) {
    this.driving = b
    this.el.speedo.classList.toggle('hidden', !b)
    if (!b) this.el.crosshair.classList.add('hidden')
  }

  setSpeed(mph) {
    if (!this.driving) return
    const v = Math.round(Math.abs(mph))
    if (this.el.speedNum.textContent !== String(v)) this.el.speedNum.textContent = String(v)
  }

  setGear(g) { if (this.el.gear.textContent !== g) this.el.gear.textContent = g }

  setWeapon(name, mag, reserve) {
    this.el.weaponName.textContent = name
    this.el.ammoMag.textContent = mag
    this.el.ammoReserve.textContent = reserve
    this.el.ammo.classList.toggle('low', mag <= 3)
  }

  setCrosshair(mode) {
    const show = mode !== 'hidden' && !this.driving
    this.el.crosshair.classList.toggle('hidden', !show)
    this.el.crosshair.classList.toggle('aim', mode === 'aim')
  }

  setPrompt(text, key = 'F') {
    if (!text) {
      this.el.prompt.classList.add('hidden')
      this.promptShown = null
      return
    }
    if (this.promptShown === text) return
    this.promptShown = text
    this.el.prompt.classList.remove('hidden')
    this.el.promptKey.textContent = key
    this.el.promptText.textContent = text
  }

  flashDamage(intensity = 1) {
    this.el.damage.style.opacity = String(Math.min(0.85, 0.35 + intensity * 0.3))
    clearTimeout(this.damageTimer)
    this.damageTimer = setTimeout(() => { this.el.damage.style.opacity = '0' }, 120)
  }

  notify(text, color = '#f6c453') {
    const d = document.createElement('div')
    d.className = 'toast'
    d.textContent = text
    d.style.borderLeftColor = color
    this.el.toasts.appendChild(d)
    while (this.el.toasts.children.length > 4) this.el.toasts.removeChild(this.el.toasts.firstChild)
    setTimeout(() => {
      d.classList.add('out')
      setTimeout(() => d.remove(), 450)
    }, 2600)
  }

  missionSplash(title, brief) {
    clearTimeout(this.splashTimer)
    this.el.splash.classList.remove('hidden', 'out')
    this.el.splashTitle.textContent = title
    this.el.splashBrief.textContent = brief
    this.splashTimer = setTimeout(() => {
      this.el.splash.classList.add('out')
      this.splashTimer = setTimeout(() => this.el.splash.classList.add('hidden'), 600)
    }, 3600)
  }

  missionComplete(title, reward) {
    this.showBanner('MISSION PASSED', `+$${Math.round(reward).toLocaleString('en-US')} · ${title}`, '#f6c453')
    this.notify('MISSION PASSED: ' + title, '#8dffb0')
  }

  missionFailed(reason) {
    this.showBanner('MISSION FAILED', reason, '#ff6a55')
  }

  showBanner(title, sub, color) {
    clearTimeout(this.bannerTimer)
    this.el.banner.classList.remove('hidden')
    this.el.bannerTitle.textContent = title
    this.el.bannerTitle.style.color = color
    this.el.bannerSub.textContent = sub || ''
    this.bannerTimer = setTimeout(() => this.el.banner.classList.add('hidden'), 3400)
  }

  showWasted(loss) {
    this.el.wastedSub.textContent = `Medical bills: -$${loss}`
    this.el.wasted.classList.remove('hidden')
  }
  hideWasted() { this.el.wasted.classList.add('hidden') }

  showPause(show) {
    this.el.pause.classList.toggle('hidden', !show)
    if (show) {
      this.el.statMissions.textContent = String(this.game.missions.completed)
      this.el.statMoney.textContent = '$' + Math.round(this.game.money).toLocaleString('en-US')
      this.el.statWanted.textContent = this.game.police.wanted > 0 ? '★'.repeat(this.game.police.wanted) : 'CLEAN'
    }
  }

  setHintGone() { this.el.hint.classList.add('gone') }

  update(dt) {
    const p = this.game.player
    if (p) {
      this.el.hpfill.style.width = Math.max(0, Math.min(100, p.hp)) + '%'
      this.el.armorfill.style.width = Math.max(0, Math.min(100, p.armor)) + '%'
      this.el.hpbar.classList.toggle('low', p.hp < 30)
    }
    // radar at ~30fps
    this.lastRadar += dt
    if (this.lastRadar > 1 / 30) {
      this.lastRadar = 0
      this.drawRadar()
    }
  }

  toScreen(wx, wz, px, pz, cos, sin, scale, cx, cy) {
    const dx = wx - px, dz = wz - pz
    return [cx + (-dx * cos + dz * sin) * scale, cy - (dx * sin + dz * cos) * scale]
  }

  drawRadar() {
    const ctx = this.ctx
    const W = 360, cx = 180, cy = 180, R = 178
    const game = this.game
    const player = game.player
    if (!player) return
    const pv = game.playerVehicle
    const px = pv ? pv.pos.x : player.pos.x
    const pz = pv ? pv.pos.z : player.pos.z
    const camYaw = game.camYaw || 0
    const speed = pv ? Math.abs(pv.speed) : 0
    const scale = pv ? Math.max(1.25, 1.75 - speed * 0.012) : 1.85
    const cos = Math.cos(camYaw), sin = Math.sin(camYaw)

    ctx.clearRect(0, 0, W, W)
    ctx.save()
    ctx.beginPath()
    ctx.arc(cx, cy, R, 0, Math.PI * 2)
    ctx.clip()

    // base
    const bg = ctx.createRadialGradient(cx, cy, 20, cx, cy, R)
    bg.addColorStop(0, '#1a241f')
    bg.addColorStop(1, '#121917')
    ctx.fillStyle = bg
    ctx.fillRect(0, 0, W, W)

    ctx.save()
    ctx.translate(cx, cy)
    ctx.transform(-cos * scale, -sin * scale, sin * scale, -cos * scale, 0, 0)

    // blocks
    ctx.fillStyle = '#232d27'
    for (const b of game.world.blocks) {
      ctx.fillRect(b.x - px - b.w / 2, b.z - pz - b.d / 2, b.w, b.d)
    }
    // buildings
    ctx.fillStyle = '#33413a'
    for (const b of game.world.buildings) {
      if (Math.abs(b.x - px) > 260 || Math.abs(b.z - pz) > 260) continue
      ctx.fillRect(b.x - px - b.w / 2, b.z - pz - b.d / 2, b.w, b.d)
    }
    // roads
    ctx.strokeStyle = '#4b5453'
    ctx.lineWidth = 16
    ctx.lineCap = 'butt'
    for (const line of game.world.lines) {
      ctx.beginPath()
      ctx.moveTo(-220 - px, line - pz)
      ctx.lineTo(220 - px, line - pz)
      ctx.stroke()
      ctx.beginPath()
      ctx.moveTo(line - px, -220 - pz)
      ctx.lineTo(line - px, 220 - pz)
      ctx.stroke()
    }
    // center lines
    ctx.strokeStyle = '#7d7a5e'
    ctx.lineWidth = 0.5
    for (const line of game.world.lines) {
      ctx.beginPath()
      ctx.moveTo(-220 - px, line - pz)
      ctx.lineTo(220 - px, line - pz)
      ctx.stroke()
      ctx.beginPath()
      ctx.moveTo(line - px, -220 - pz)
      ctx.lineTo(line - px, 220 - pz)
      ctx.stroke()
    }
    ctx.restore()

    // vehicle blips
    for (const v of game.vehicles.vehicles) {
      if (v === pv || v.destroyed || !v.group.visible) continue
      const d = Math.hypot(v.pos.x - px, v.pos.z - pz)
      if (d > 130) continue
      const [sx, sy] = this.toScreen(v.pos.x, v.pos.z, px, pz, cos, sin, scale, cx, cy)
      if (v.isPolice) {
        ctx.fillStyle = Math.sin(performance.now() * 0.01) > 0 ? '#6da6ff' : '#ff5a5a'
        ctx.beginPath(); ctx.arc(sx, sy, 2.6, 0, Math.PI * 2); ctx.fill()
      } else if (v.traffic) {
        ctx.fillStyle = 'rgba(210,216,210,0.55)'
        ctx.beginPath(); ctx.arc(sx, sy, 1.5, 0, Math.PI * 2); ctx.fill()
      }
    }
    // peds
    ctx.fillStyle = 'rgba(230,220,200,0.4)'
    for (const a of game.peds.actors) {
      if (a.dead) continue
      const d = Math.hypot(a.pos.x - px, a.pos.z - pz)
      if (d > 65) continue
      const [sx, sy] = this.toScreen(a.pos.x, a.pos.z, px, pz, cos, sin, scale, cx, cy)
      ctx.beginPath(); ctx.arc(sx, sy, 1.1, 0, Math.PI * 2); ctx.fill()
    }

    // marker
    if (this.marker) {
      const [sx, sy] = this.toScreen(this.marker.x, this.marker.z, px, pz, cos, sin, scale, cx, cy)
      let dx = sx - cx, dy = sy - cy
      let dist = Math.hypot(dx, dy)
      const max = R * 0.86
      let clamped = false
      if (dist > max) {
        const k = max / (dist || 1)
        dx *= k; dy *= k
        dist = max
        clamped = true
      }
      const mx = cx + dx, my = cy + dy
      const color = this.marker.color || '#ffc84a'
      const pulse = 1 + Math.sin(performance.now() * 0.006) * 0.12
      ctx.save()
      ctx.translate(mx, my)
      if (clamped) {
        ctx.rotate(Math.atan2(dy, dx) + Math.PI / 2)
        ctx.fillStyle = color
        ctx.beginPath(); ctx.moveTo(0, -9); ctx.lineTo(7, 2); ctx.lineTo(-7, 2); ctx.closePath(); ctx.fill()
      } else {
        ctx.fillStyle = 'rgba(0,0,0,0.55)'
        ctx.beginPath(); ctx.arc(0, 0, 9 * pulse, 0, Math.PI * 2); ctx.fill()
        ctx.fillStyle = color
        ctx.beginPath(); ctx.arc(0, 0, 5.2 * pulse, 0, Math.PI * 2); ctx.fill()
        ctx.strokeStyle = 'rgba(255,255,255,0.85)'
        ctx.lineWidth = 1.4
        ctx.stroke()
      }
      ctx.restore()
    }

    // player arrow
    const heading = pv ? pv.yaw : player.yaw
    const rel = heading - camYaw
    ctx.save()
    ctx.translate(cx, cy)
    ctx.rotate(rel)
    ctx.beginPath()
    ctx.moveTo(0, -10)
    ctx.lineTo(7.5, 8)
    ctx.lineTo(0, 4.5)
    ctx.lineTo(-7.5, 8)
    ctx.closePath()
    ctx.fillStyle = '#ffffff'
    ctx.shadowColor = 'rgba(0,0,0,0.9)'
    ctx.shadowBlur = 5
    ctx.fill()
    ctx.restore()

    // north marker
    const nx = cx - Math.sin(camYaw) * R * 0.9
    const ny = cy + Math.cos(camYaw) * R * 0.9
    ctx.fillStyle = 'rgba(246,196,83,0.9)'
    ctx.font = 'bold 15px Arial'
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText('N', nx, ny)

    ctx.restore()

    // inner border
    ctx.strokeStyle = 'rgba(0,0,0,0.65)'
    ctx.lineWidth = 4
    ctx.beginPath(); ctx.arc(cx, cy, R - 1, 0, Math.PI * 2); ctx.stroke()
  }
}

