  const r = 82
  camTarget.set(0, 6, 0)
  const want = new THREE.Vector3(
    10 + Math.sin(menuAngle) * r,
    30 + Math.sin(menuAngle * 0.7) * 7,
    8 + Math.cos(menuAngle) * r
  )
  camera.position.lerp(want, 1 - Math.exp(-2.2 * dt))
  camera.lookAt(camTarget)
  return
}

